        gpiod_line_release(line_gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line_gpio_alt, &alt_config, 0) < 0) {
        perror("Error requesting GPIO line (ALT)");
        gpiod_line_release(line_gpio);
        gpiod_line_release(line_gpio_alt);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

