#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_PIN_ALT 3

static struct gpiod_chip *chip;
static struct gpiod_line *line_gpio;
static struct gpiod_line *line_gpio_alt;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec sleep_time = {0, 100000000L}; // 0.1 seconds
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get line for GPIO 2
    line_gpio = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line_gpio) {
        perror("Error getting line for GPIO 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get line for GPIO 3 (alternative)
    line_gpio_alt = gpiod_chip_get_line(chip, GPIO_PIN_ALT);
    if (!line_gpio_alt) {
        perror("Error getting line for GPIO 3");
        gpiod_line_release(line_gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 2 as output
    ret = gpiod_line_request_output(line_gpio, "my_app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 2 as output");
        gpiod_line_release(line_gpio_alt);
        gpiod_line_release(line_gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 3 as output
    ret = gpiod_line_request_output(line_gpio_alt, "my_app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 3 as output");
        gpiod_line_release(line_gpio_alt);
        gpiod_line_release(line_gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Set GPIO 2 HIGH
        ret = gpiod_line_set_value(line_gpio, 1);
        if (ret < 0) {
            perror("Error setting GPIO 2 HIGH");
        } else {
            printf("GPIO 2 set HIGH\n");
        }

        // Set GPIO 3 HIGH
        ret = gpiod_line_set_value(line_gpio_alt, 1);
        if (ret < 0) {
            perror("Error setting GPIO 3 HIGH");
        } else {
            printf("GPIO 3 set HIGH\n");
        }

        // Sleep for 0.1 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }

        // Set GPIO 2 LOW
        ret = gpiod_line_set_value(line_gpio, 0);
        if (ret < 0) {
            perror("Error setting GPIO 2 LOW");
        } else {
            printf("GPIO 2 set LOW\n");
        }

        // Set GPIO 3 LOW
        ret = gpiod_line_set_value(line_gpio_alt, 0);
        if (ret < 0) {
            perror("Error setting GPIO 3 LOW");
        } else {
            printf("GPIO 3 set LOW\n");
        }
    }

    // Release GPIO resources
    gpiod_line_release(line_gpio_alt);
    gpiod_line_release(line_gpio);
    gpiod_chip_close(chip);

    printf("GPIO control stopped.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_LINE "gpio%d"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct gpiod_line_request_config config;
    struct gpiod_line_request_config request_config;
    struct gpiod_line_request_config export_config;
    struct gpiod_line_request_config unexport_config;
    int ret;
    struct timespec sleep_time;
    struct timespec read_time;
    int value;
    char value_str[10];
    struct gpiod_line_request *request;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Export GPIO line
    snprintf(GPIO_LINE, sizeof(GPIO_LINE), "%d", GPIO_PIN);
    snprintf(GPIO_CHIP, sizeof(GPIO_CHIP), "%s", GPIO_CHIP);

    // Export GPIO line
    export_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    export_config.consumer = "gpio_output_test";
    export_config.request_line = GPIO_LINE;
    export_config.request_chip = GPIO_CHIP;

    ret = gpiod_chip_open_by_name(GPIO_CHIP, &chip);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(-ret));
        return 1;
    }

    ret = gpiod_chip_get_line(chip, GPIO_LINE, &line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request(line, &export_config, &request);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(-ret));
        gpiod_line_release(line, request);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up sleep time for 5 seconds
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    // Main loop
    while (keep_running) {
        // Set GPIO high
        config.consumer = "gpio_output_test";
        config.request_line = GPIO_LINE;
        config.request_chip = GPIO_CHIP;
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.value = 1;

        ret = gpiod_line_request(line, &config, &request);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line high: %s\n", strerror(-ret));
            gpiod_line_release(line, request);
            gpiod_chip_close(chip);
            return 1;
        }

        nanosleep(&sleep_time, NULL);

        // Read GPIO value
        config.consumer = "gpio_output_test";
        config.request_line = GPIO_LINE;
        config.request_chip = GPIO_CHIP;
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        ret = gpiod_line_request(line, &config, &request);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line for reading: %s\n", strerror(-ret));
            gpiod_line_release(line, request);
            gpiod_chip_close(chip);
            return 1;
        }

        ret = gpiod_line_get_value(line, &value);
        if (ret < 0) {
            fprintf(stderr, "Error getting GPIO value: %s\n", strerror(-ret));
            gpiod_line_release(line, request);
            gpiod_chip_close(chip);
            return 1;
        }

        if (value < 0 || value > 1) {
            fprintf(stderr, "Invalid GPIO value: %d\n", value);
            gpiod_line_release(line, request);
            gpiod_chip_close(chip);
            return 1;
        }

        snprintf(value_str, sizeof(value_str), "%d", value);
        printf("GPIO %s set to %s\n", GPIO_LINE, value_str);

        // Set GPIO low
        config.consumer = "gpio_output_test";
        config.request_line = GPIO_LINE;
        config.request_chip = GPIO_CHIP;
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.value = 0;

        ret = gpiod_line_request(line, &config, &request);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line low: %s\n", strerror(-ret));
            gpiod_line_release(line, request);
            gpiod_chip_close(chip);
            return 1;
        }

        nanosleep(&sleep_time, NULL);

        // Release GPIO line
        ret = gpiod_line_release(line, request);
        if (ret < 0) {
            fprintf(stderr, "Error releasing GPIO line: %s\n", strerror(-ret));
            gpiod_chip_close(chip);
            return 1;
        }

        gpiod_line_release(line, request);
        gpiod_chip_close(chip);
    }

    return 0;
}

