    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit word from the I2C device
int read_word(int fd, unsigned char reg) {
    unsigned char buffer[2];
    int result;

    // Write the register address to the device
    result = write(fd, &reg, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read two bytes from the device
    result = read(fd, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit word
    return (buffer[0] << 8) | buffer[1];
}

