            fprintf(stderr, "Failed to configure ADS1115. Exiting.\n");
            break;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read the conversion result
        uint16_t conversion_result;
        if (read_i2c_reg(i2c_fd, ADS1115_REG_CONVERT, &conversion_result) < 0) {
            fprintf(stderr, "Failed to read conversion result. Exiting.\n");
            break;
        }

        // Print the conversion result
        printf("ADC Value: %d\n", conversion_result);

        // Wait for 0.1 seconds
        usleep(100000); // 100ms
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    config.consumer = "my_gpio_app";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d requested as output\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Wait for 1 second
        sleep(1);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO line
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d released\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    result = gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO %d, frequency %d Hz, range %d. Press Ctrl+C to exit.\n", PWM_GPIO, PWM_FREQUENCY, PWM_RANGE);

    while (running) {
        // Set PWM duty cycle (0-1000)
        int duty_cycle = 500; // 50% duty cycle
        gpioPWM(PWM_GPIO, duty_cycle);

        // Print the state
        printf("PWM: %d\n", duty_cycle);

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500000 microseconds = 0.5 seconds
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define GPIO line names
#define TRIGGER_LINE "17"
#define ECHO_LINE "27"

// Define speed of sound in cm/s
#define SPEED_OF_SOUND 34300.0

// Define timeout in microseconds
#define TIMEOUT 1000000 // 1 second

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
int trigger_pulse(void);
int read_echo(void);
double calculate_distance(int pulse_duration);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initializes the GPIO chip and lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_LINE);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line %s: %s\n", TRIGGER_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_LINE);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line %s: %s\n", ECHO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Request trigger line for output
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line %s for output: %s\n", TRIGGER_LINE, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    // Request echo line for input
    ret = gpiod_line_request_input(echo_line, "echo", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line %s for input: %s\n", ECHO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Generates a 10us trigger pulse on the trigger line
int trigger_pulse(void) {
    int ret;
    struct gpiod_line_request_config config;

    // Set the trigger line to output
    config.consumer = "trigger";
    config.consumer_data = NULL;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line for output: %s\n", strerror(errno));
        return -1;
    }

    // Set the trigger line to high
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger line value: %s\n", strerror(errno));
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Wait for 10us
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10000; // 10 microseconds
    nanosleep(&ts, NULL);

    // Set the trigger line to low
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger line value: %s\n", strerror(errno));
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Release the trigger line
    ret = gpiod_line_release(trigger_line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing trigger line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Reads the echo pulse duration on the echo line
int read_echo(void) {
    struct timespec start, end;
    int ret;
    long long duration;

    // Wait for the echo line to go high
    ret = gpiod_line_set_fd(echo_line, fileno(STDIN)); // Use fileno to get the file descriptor
    if (ret < 0) {
        fprintf(stderr, "Error setting echo line fd: %s\n", strerror(errno));
        return -1;
    }

    ret = gpiod_line_request_input(echo_line, "echo", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line for input: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the echo line to go high (with timeout)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1;
        }
    }

    // Wait for the echo line to go low (with timeout)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
    }

    // Get the duration of the pulse
    clock_gettime(CLOCK_MONOTONIC, &end);
    duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    // Release the echo line
    ret = gpiod_line_release(echo_line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing echo line: %s\n", strerror(errno));
        return -1;
    }

    return (int)duration;
}

// Calculates the distance in centimeters
double calculate_distance(int pulse_duration) {
    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Cleans up the GPIO resources
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int pulse_duration;
    double distance;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger a pulse
        if (trigger_pulse() < 0) {
            fprintf(stderr, "Error triggering pulse. Continuing.\n");
            sleep(60);
            continue;
        }

        // Read the echo pulse duration
        pulse_duration = read_echo();
        if (pulse_duration < 0) {
            fprintf(stderr, "Error reading echo. Continuing.\n");
            sleep(60);
            continue;
        }

        // Calculate the distance
        distance = calculate_distance(pulse_duration);

        // Get current time
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Print the distance with timestamp
        printf("[%s] Distance: %.2f cm\n", timestamp, distance);

        // Wait for 60 seconds
        sleep(60);
    }

    // Clean up GPIO resources
    cleanup_gpio();

    printf("GPIO resources released. Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x28

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0040  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0001 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0003 // Non-latching comparator

// Global variables
int i2c_fd;
volatile sig_atomic_t running = 1;

// Function prototypes
int ads1115_init(int fd);
int ads1115_read(int fd, int16_t *value);
void signal_handler(int sig);

// Signal handler to catch Ctrl+C and exit gracefully
void signal_handler(int sig) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the ADS1115
int ads1115_init(int fd) {
    uint8_t config_data[3];

    // Configure the configuration register
    config_data[0] = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS;
    config_data[1] = CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON;
    if (write(fd, config_data, 2) != 2) {
        perror("Failed to write to configuration register");
        return -1;
    }

    return 0;
}

// Function to read a single-ended channel from the ADS1115
int ads1115_read(int fd, int16_t *value) {
    uint8_t read_data[2];
    uint8_t config_data[3];

    // Configure the configuration register for a single conversion
    config_data[0] = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS;
    config_data[1] = CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON;
    if (write(fd, config_data, 2) != 2) {
        perror("Failed to write to configuration register");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion register
    if (read(fd, read_data, 2) != 2) {
        perror("Failed to read from conversion register");
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *value = (int16_t)((read_data[0] << 8) | read_data[1]);

    return 0;
}

int main() {
    int16_t adc_value;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the ADS1115
    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADS1115 initialized successfully.\n");

    // Main loop
    while (running) {
        // Read the ADC value
        if (ads1115_read(i2c_fd, &adc_value) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print the ADC value and timestamp
            printf("%s: ADC Value = %d\n", timestamp, adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

