#include <errno.h>

// Define the GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIOLINE 17

// Global variable to store the GPIO line
struct gpiod_line *gpio_line = NULL;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    exit(0);
}

// Function to initialize the GPIO line
int initialize_gpio(struct gpiod_line **gpio_line) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *gpio_line = gpiod_chip_get_line(chip, GPIOLINE);
    if (!*gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(*gpio_line, "my_gpio", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the GPIO line state
int set_gpio_state(struct gpiod_line *gpio_line, int state) {
    if (gpiod_line_set_value(gpio_line, state) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Function to read the GPIO line state
int read_gpio_state(struct gpiod_line *gpio_line) {
    int value = gpiod_line_get_value(gpio_line);
    if (value < 0) {
        perror("Error reading GPIO line value");
        return -1;
    }
    return value;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO line
    if (initialize_gpio(&gpio_line) < 0) {
        return 1;
    }

    printf("GPIO %d initialized as output.\n", GPIOLINE);

    // Main loop to toggle the GPIO state
    while (1) {
        // Read the current state
        int current_state = read_gpio_state(gpio_line);
        if (current_state < 0) {
            fprintf(stderr, "Error reading state, exiting.\n");
            break;
        }

        // Toggle the state
        int new_state = !current_state;
        if (set_gpio_state(gpio_line, new_state) < 0) {
            fprintf(stderr, "Error setting state, exiting.\n");
            break;
        }

        // Print the new state
        printf("GPIO %d set to %d\n", GPIOLINE, new_state);
        sleep(1); // Wait for 1 second
    }

    // Clean up and exit
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    gpiod_chip_close(gpiod_chip_get_by_name(GPIOCHIP));

    return 0;
}

