// Define GPIO pins
#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define GPIO_PIN_3 22
#define GPIO_PIN_4 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(void);
int set_gpio_output(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int read_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize the GPIO chip
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    return 0;
}

// Function to set a GPIO pin as output
int set_gpio_output(int gpio_pin) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_request_output(line, "output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO pin
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read the value of a GPIO pin
int read_gpio_value(int gpio_pin) {
    struct gpiod_line *line = NULL;
    int ret;
    int value;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("Error getting GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    value = ret;
    gpiod_line_release(line);
    return value;
}

// Function to cleanup the GPIO chip
void cleanup_gpio(void) {
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int state = 0;
    int i;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set GPIO pins as output
    for (i = 0; i < 4; i++) {
        if (set_gpio_output(GPIO_PIN_1 + i) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output. Exiting.\n", GPIO_PIN_1 + i);
            cleanup_gpio();
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Set output state
        for (i = 0; i < 4; i++) {
            if (set_gpio_value(GPIO_PIN_1 + i, state) != 0) {
                fprintf(stderr, "Failed to set GPIO %d value. Continuing.\n", GPIO_PIN_1 + i);
                continue; // Continue to the next GPIO
            }
        }

        // Print the state applied to each GPIO pin
        printf("GPIO States: ");
        for (i = 0; i < 4; i++) {
            printf("GPIO %d: %d ", GPIO_PIN_1 + i, read_gpio_value(GPIO_PIN_1 + i));
        }
        printf("\n");

        // Wait for 2 seconds
        sleep(2);
    }

    return 0;
}

