    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        running = 0; // Set the running flag to 0 to exit the main loop
    }
}

// Function to set up the I2C bus
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read bytes from the I2C device
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    int bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Function to write a byte to the I2C device
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Function to read temperature from the SI7021
float read_temperature(int fd) {
    uint8_t data[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write_byte(fd, TEMP_REG, TEMP_MEASURE_CMD) != 0) {
            fprintf(stderr, "Error triggering temperature measurement. Retrying...\n");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        usleep(10000); // Wait for measurement (datasheet specifies 12.1ms for temperature)

        if (i2c_read_bytes(fd, TEMP_REG, data, 2) != 0) {
            fprintf(stderr, "Error reading temperature data. Retrying...\n");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Convert raw data to temperature (Celsius)
        int16_t raw_temp = (data[0] << 8) | data[1];
        float temperature = (175.72 * raw_temp / 65536.0) - 46.85;

        return temperature;
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1000.0; // Indicate an error
}

// Function to print the temperature to the console
void print_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, SI7021_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("SI7021 Temperature Sensor Program\n");

    // Main loop
    while (running) {
        float temperature = read_temperature(i2c_fd);

        if (temperature > -999.0) { // Check for valid temperature reading
            print_temperature(temperature);
        } else {
            fprintf(stderr, "Invalid temperature reading. Skipping.\n");
        }

        sleep(5); // Wait 5 seconds
    }

    // Cleanup
    close(i2c_fd);
    printf("I2C connection closed.\n");

    return EXIT_SUCCESS;
}

