// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0040  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0001 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0003 // Non-latching comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the I2C device
int write_i2c_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;       // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the I2C device
int read_i2c_reg(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device (address)");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the I2C device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure ADS1115 for single-ended AIN0, +/-4.096V, single-shot mode, 128 SPS
        uint16_t config_value = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON;

        if (write_i2c_reg(i2c_fd, ADS1115_REG_CONFIG, config_value) < 0) {
            fprintf(stderr, "Failed to configure ADS1115. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read the conversion result
        uint16_t conversion_result;
        if (read_i2c_reg(i2c_fd, ADS1115_REG_CONVERT, &conversion_result) < 0) {
            fprintf(stderr, "Failed to read conversion result. Exiting.\n");
            close(i2c_fd);
