#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting...\n", signum);
}

int setup_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 5;                             // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // No data available
        }
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[BUFFER_SIZE];
    fd_set readfds;
    struct timeval timeout;

    printf("Starting UART communication...\n");

    while (program_running) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = 1;  // Timeout after 1 second
        timeout.tv_usec = 0;

        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("Error in select");
            break;
        } else if (select_result == 0) {
            // Timeout occurred, no data available
            continue;
        } else {
            // Data is available
            int bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
            if (bytes_read > 0) {
                buffer[bytes_read] = '\0';
                printf("Received: %s\n", buffer);
            } else if (bytes_read == -1) {
                perror("Error reading from UART");
                break;
            }
        }
    }

    printf("Cleaning up and exiting...\n");

    if (uart_fd != -1) {
        close(uart_fd);
    }

    return EXIT_SUCCESS;
}

