int read_dht11_data(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    // Set GPIO as output
    if (gpiod_line_set_direction(line, "out") < 0) {
        perror("Failed to set GPIO direction to output");
        return -1;
    }

    // Send start signal
    gpiod_line_set_value(line, 0);
    usleep(18000); // 18ms
    gpiod_line_set_value(line, 1);
    usleep(20); // 20us
    gpiod_line_set_value(line, 0);
    usleep(40); // 40us

    // Set GPIO as input
    if (gpiod_line_set_direction(line, "in") < 0) {
        perror("Failed to set GPIO direction to input");
        return -1;
    }

    // Read data
    for (i = 0; i < MAX_TIMINGS; i++) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO value");
            return -1;
        }

        if (value == 0) {
            data[bit_count / 8] <<= 1;
            if (bit_count % 8 == 7) {
                data[bit_count / 8] |= 1;
            }
            bit_count++;
        } else {
            bit_count = 0; // Reset if signal is high
        }

        usleep(30); // 30us
    }

    // Validate data
    if (bit_count != 40) {
        fprintf(stderr, "Invalid data length: %d\n", bit_count);
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

