#include <pigpio.h>

#define PWM_PIN 2
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 as PWM output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("PWM output on GPIO %d. Press Ctrl+C to exit.\n", PWM_PIN);

    while (!terminate) {
        // Generate PWM signal
        result = gpioPWM(PWM_PIN, 500); // 50% duty cycle
        if (result != 0) {
            fprintf(stderr, "Error setting PWM: %d\n", result);
        }

        printf("PWM: %d\n", result);

        gpioDelay(150000); // 0.15 seconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

