#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// OPT3001 I2C address
#define OPT3001_ADDR 0x44

// OPT3001 register addresses
#define OPT3001_RESULT_REG 0x00
#define OPT3001_CONFIG_REG 0x01

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the OPT3001
int16_t read_opt3001_value(int fd) {
    int16_t value;
    uint8_t buffer[2];

    // Write the register address to be read
    if (write(fd, &OPT3001_RESULT_REG, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Read two bytes from the OPT3001
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    value = (buffer[0] << 8) | buffer[1];

    return value;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the OPT3001
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print the OPT3001 value
    while (1) {
        int16_t value = read_opt3001_value(i2c_fd);
        if (value != -1) {
            // Convert the raw value to current and voltage
            float current_mA = (float)value / 128.0;
            float voltage_mv = (float)(value * 3.2) / 1000.0;

            // Print the current and voltage to the console
            printf("Current: %.2f mA, Voltage: %.2f V\n", current_mA, voltage_mv);
        } else {
            fprintf(stderr, "Failed to read OPT3001 value\n");
        }

        sleep(1); // Wait for 1 second
    }

    // The program should never reach here due to the infinite loop,
    // but this ensures that the I2C device is closed if the loop is ever broken.
    close(i2c_fd);
    return 0;
}

