static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct timespec sleep_time = {0, 500000000}; // 0.5 seconds
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request;
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    request = gpiod_line_request(line, &config, 0);
    if (!request) {
        fprintf(stderr, "Error: Could not request GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d high: %d\n", GPIO_PIN, ret);
        } else {
            printf("GPIO %d set HIGH\n", GPIO_PIN);
        }

        // Sleep for 0.5 seconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d low: %d\n", GPIO_PIN, ret);
        } else {
            printf("GPIO %d set LOW\n", GPIO_PIN);
        }

        // Sleep for 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    gpiod_line_release(request);

    // Release GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int setup_uart(const char *device, speed_t baud_rate) {
    int uart_fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = TIMEOUT_MS / 100;              // Timeout of 100ms

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return -1;
    }

    return uart_fd;
}

int read_uart(int uart_fd) {
    char buffer[256];
    ssize_t bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return -1; // Device not ready
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("UART setup complete. Reading data...\n");

    while (program_running) {
        int bytes_read = read_uart(uart_fd);
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read == -1) {
            // Device not ready, wait a bit before retrying
            usleep(100000); // 100ms
            continue;
        } else {
            // Timeout occurred, device might be disconnected or not responding
            fprintf(stderr, "Timeout occurred. Check device connection.\n");
            break; // Exit the loop, possibly to exit the program
        }
    }

    close(uart_fd);
    printf("UART closed.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 milliseconds

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Set GPIO high
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d high: %s\n", GPIO_PIN, strerror(errno));
        } else {
            printf("GPIO %d set HIGH\n", GPIO_PIN);
        }

        // Set GPIO low
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d low: %s\n", GPIO_PIN, strerror(errno));
        } else {
            printf("GPIO %d set LOW\n", GPIO_PIN);
        }

        // Sleep for 10 milliseconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
            }
        }
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        fprintf(stderr, "Error closing GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

