        perror("gpiod_line_request_output");
        gpiod_line_release(line_1);
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_2, "output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line_1);
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_3, "output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line_1);
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Set GPIO states
        ret = gpiod_line_set_value(line_1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break; // Exit loop on error
