#include <errno.h>

// Define GPIO chip and line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 2

// Define GPIO attributes
#define GPIO_DIRECTION "out"
#define GPIO_VALUE "0"

// Define cycle duration (seconds)
#define CYCLE_DURATION 60

// Define interrupt duration (seconds)
#define INTERRUPT_DURATION 5

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(void);
int validate_sensor_reading(int sensor_value);
int apply_output(int sensor_value);
void signal_handler(int sig);
void cleanup(void);

// Signal handler for graceful exit
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read the sensor value
int read_sensor(void) {
    // Simulate reading a sensor value (replace with actual sensor reading logic)
    // For example, read from a file or a networked service
    FILE *fp;
    char buffer[256];
    int sensor_value;

    fp = fopen("sensor_data.txt", "r");
    if (fp == NULL) {
        perror("Error opening sensor_data.txt");
        return -1; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        sensor_value = atoi(buffer);
        fclose(fp);
        return sensor_value;
    } else {
        fclose(fp);
        fprintf(stderr, "Error reading sensor data.\n");
        return -1; // Indicate error
    }
}

// Function to validate the sensor reading
int validate_sensor_reading(int sensor_value) {
    if (sensor_value >= 0 && sensor_value <= 255) {
        return 0; // Valid
    } else {
        fprintf(stderr, "Invalid sensor reading: %d\n", sensor_value);
        return -1; // Invalid
    }
}

// Function to apply the output based on the sensor reading
int apply_output(int sensor_value) {
    char value_str[2];
    snprintf(value_str, sizeof(value_str), "%d", sensor_value);

    int ret = gpiod_line_set_value(line, value_str);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    printf("Applied output: %s\n", value_str);
    return 0;
}

// Function to perform cleanup before exiting
void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    int ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, skipping cycle.\n");
            sleep(CYCLE_DURATION);
            continue;
        }

        // Validate sensor reading
        if (validate_sensor_reading(sensor_value) == 0) {
            // Apply output
            if (apply_output(sensor_value) != 0) {
                fprintf(stderr, "Error applying output.\n");
            }
        } else {
            fprintf(stderr, "Invalid sensor reading, skipping cycle.\n");
        }

        // Interrupt: set GPIO high for 5 seconds
        ret = gpiod_line_set_value(line, "1");
        if (ret < 0) {
            perror("Error setting GPIO high during interrupt");
        }
        sleep(INTERRUPT_DURATION);
        ret = gpiod_line_set_value(line, "0");
        if (ret < 0) {
            perror("Error setting GPIO low during interrupt");
        }

        // Wait for the next cycle
        sleep(CYCLE_DURATION);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

