    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIOCHIP);
        return EXIT_FAILURE;
    }

    // Get line handles for GPIOs 17, 22, and 27
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line22 = gpiod_chip_get_line(chip, GPIO22);
    line27 = gpiod_chip_get_line(chip, GPIO27);

    if (!line17 || !line22 || !line27) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", (line17 == NULL) ? GPIO17 : (line22 == NULL) ? GPIO22 : GPIO27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line17, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d for output: %d\n", GPIO17, ret);
        gpiod_line_release(line17);
        gpiod_line_release(line22);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line22, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d for output: %d\n", GPIO22, ret);
        gpiod_line_release(line17);
        gpiod_line_release(line22);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line27, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d for output: %d\n", GPIO27, ret);
        gpiod_line_release(line17);
        gpiod_line_release(line22);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        // Set GPIO 17 HIGH
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d HIGH: %d\n", GPIO17, ret);
        } else {
            printf("GPIO %d set HIGH\n", GPIO17);
        }

        // Set GPIO 22 LOW
        ret = gpiod_line_set_value(line22, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d LOW: %d\n", GPIO22, ret);
        } else {
