static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line *line_3;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds
    int ret;
    int value, value_3;
    char value_str[10];
    char value_3_str[10];
    struct timespec start_time, current_time;
    double elapsed_time;

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    line_3 = gpiod_chip_get_line(chip, GPIO_LINE_3);
    if (!line_3) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_3, "output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read GPIO value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            gpiod_line_release(line);
            gpiod_line_release(line_3);
            gpiod_chip_close(chip);
            return 1;
        }

        // Read GPIO 3 value
        value_3 = gpiod_line_get_value(line_3);
        if (value_3 < 0) {
            perror("gpiod_line_get_value");
            gpiod_line_release(line);
            gpiod_line_release(line_3);
            gpiod_chip_close(chip);
            return 1;
        }

        // Convert to string
        snprintf(value_str, sizeof(value_str), "%d", value);
        snprintf(value_3_str, sizeof(value_3_str), "%d", value_3);

        // Get current time
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
            perror("clock_gettime");
            gpiod_line_release(line);
            gpiod_line_release(line_3);
            gpiod_chip_close(chip);
            return 1;
        }

        // Calculate elapsed time
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        // Print the state and elapsed time
        printf("%s - GPIO %d: %s, GPIO %d: %s, Elapsed Time: %.2f seconds\n",
               value_str, GPIO_LINE, value_str, GPIO_LINE_3, value_3_str, elapsed_time);

        // Sleep for 0.1 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("nanosleep");
            gpiod_line_release(line);
            gpiod_line_release(line_3);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Release GPIO line
    gpiod_line_release(line);
    gpiod_line_release(line_3);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

