// Function to set the state of a GPIO pin
int set_gpio_state(int gpio_pin, int state) {
    struct gpiod_line *line = NULL;
    int ret;

    // Open the GPIO line
    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    // Set the GPIO line direction to output
    ret = gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set direction for GPIO %d: %s\n", gpio_pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    // Set the GPIO line value
    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO %d: %s\n", gpio_pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    // Close the GPIO line
    gpiod_line_release(line);

    return 0;
}

int main() {
    int state1, state2, state3;
    int ret;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Main loop
    while (1) {
        // Set the state of GPIO pins
        state1 = 1; // HIGH
        state2 = 0; // LOW
        state3 = 0; // LOW

        // Set the state of GPIO 17
        ret = set_gpio_state(GPIO_PIN_1, state1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d state\n", GPIO_PIN_1);
        }
        printf("GPIO %d set to %d\n", GPIO_PIN_1, state1);

        // Set the state of GPIO 22
        ret = set_gpio_state(GPIO_PIN_2, state2);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d state\n", GPIO_PIN_2);
        }
        printf("GPIO %d set to %d\n", GPIO_PIN_2, state2);

        // Set the state of GPIO 27
        ret = set_gpio_state(GPIO_PIN_3, state3);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d state\n", GPIO_PIN_3);
        }
        printf("GPIO %d set to %d\n", GPIO_PIN_3, state3);

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // The program should never reach here due to the infinite loop.
    // However, this ensures that the GPIO chip is closed if the loop is ever exited.
    gpiod_chip_close(chip);

    return 0;
