#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN 4
#define ENABLE_PIN 12
#define CS_PIN 18

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 50

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_spi();
void set_pwm(int duty_cycle);
void enable_pwm();
void disable_pwm();
void disable_spi();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);

    gpioPWM(PWM_PIN, 0); // Initialize PWM to 0
    gpioWrite(ENABLE_PIN, 1); // Enable PWM initially
    gpioWrite(CS_PIN, 1); // Ensure CS is high initially

    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Set PWM duty cycle
void set_pwm(int duty_cycle) {
    gpioPWM(PWM_PIN, duty_cycle);
}

// Enable PWM
void enable_pwm() {
    gpioWrite(ENABLE_PIN, 0); // Enable PWM
}

// Disable PWM
void disable_pwm() {
    gpioWrite(ENABLE_PIN, 1); // Disable PWM
}

// Disable SPI
void disable_spi() {
    spiClose(spi_handle);
}

// Cleanup resources before exiting
void cleanup() {
    disable_pwm(); // Ensure PWM is disabled
    disable_spi(); // Ensure SPI is disabled
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi()) {
        cleanup();
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Enable PWM
        enable_pwm();

        // Set PWM duty cycle
        set_pwm(PWM_DUTY_CYCLE);

        // Enable SPI
        gpioWrite(CS_PIN, 0); // Select the slave
        spiXfer(spi_handle, NULL, NULL, 0); // Dummy transfer
        gpioWrite(CS_PIN, 1); // Deselect the slave

        // Disable PWM
        disable_pwm();

        // Small delay
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

