#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN 17
#define ENABLE_PIN 18
#define CS_PIN 27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_pwm_value(int value);
void set_pwm_frequency(int frequency);
void set_pwm_range(int range);
void enable_pwm();
void disable_pwm();
void disable_pwm();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set PWM_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set ENABLE_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CS_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and range
    if (set_pwm_frequency(PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }
    if (set_pwm_range(PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Set PWM value
void set_pwm_value(int value) {
    if (value < 0 || value > PWM_RANGE) {
        fprintf(stderr, "Invalid PWM value: %d\n", value);
        return;
    }

    gpioPWM(PWM_PIN, value);
    printf("PWM value set to: %d\n", value);
}

// Set PWM frequency
void set_pwm_frequency(int frequency) {
    if (frequency < 100 || frequency > 20000) {
        fprintf(stderr, "Invalid PWM frequency: %d\n", frequency);
        return;
    }

    gpioSetPWMfrequency(PWM_PIN, frequency);
    printf("PWM frequency set to: %d Hz\n", frequency);
}

// Set PWM range
void set_pwm_range(int range) {
    if (range < 0 || range > 1000) {
        fprintf(stderr, "Invalid PWM range: %d\n", range);
        return;
    }

    gpioSetPWMrange(PWM_PIN, range);
    printf("PWM range set to: %d\n", range);
}

// Enable PWM
void enable_pwm() {
    gpioWrite(ENABLE_PIN, 1);
    printf("PWM enabled\n");
}

// Disable PWM
void disable_pwm() {
    gpioWrite(ENABLE_PIN, 0);
    printf("PWM disabled\n");
}

// Disable PWM
void disable_pwm() {
    gpioWrite(ENABLE_PIN, 0);
    printf("PWM disabled\n");
}

// Cleanup GPIO
void cleanup_gpio() {
    printf("Cleaning up GPIO...\n");
    disable_pwm(); // Ensure PWM is disabled
    gpioTerminate();
    printf("GPIO terminated\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("PWM control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Enable PWM
        enable_pwm();

        // Set PWM value
        set_pwm_value(500);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds

        // Disable PWM
        disable_pwm();
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE "w1_slave"

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nExiting program...\n");
    }
}

// Function to read temperature from DS18B20 sensor
float read_temperature(const char *device_dir) {
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s/%s", device_dir, W1_SLAVE_FILE);

    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        perror("Error opening w1_slave file");
        return -273.15; // Return absolute zero on error
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        perror("Error reading w1_slave file");
        return -273.15; // Return absolute zero on error
    }
    buffer[bytes_read] = '\0';

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC check failed\n");
        return -273.15; // Indicate CRC error
    }

    // Extract temperature data
    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found\n");
        return -273.15; // Indicate error
    }

    long temperature_raw = strtol(temp_str + 2, NULL, 10);
    return (float)temperature_raw / 1000.0;
}

int main() {
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    DIR *dir;
    struct dirent *entry;
    char device_dir[256];

    // Find DS18B20 device directory
    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("Error opening " W1_DEVICES_DIR);
        return 1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            snprintf(device_dir, sizeof(device_dir), "%s/%s", W1_DEVICES_DIR, entry->d_name);
            printf("Found DS18B20 device: %s\n", device_dir);
            break;
        }
    }

    closedir(dir);

    if (strlen(device_dir) == 0) {
        fprintf(stderr, "DS18B20 device not found\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        float temperature = read_temperature(device_dir);
        if (temperature != -273.15) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(5);
    }

    // Cleanup (should not be reached if signal handler works correctly)
    // No specific w1-gpio cleanup needed, sysfs handles it.

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// HTU21D I2C address
#define HTU21D_ADDR 0x40

// HTU21D commands
#define HTU21D_TEMP_MEASURE 0xE3
#define HTU21D_HUMID_MEASURE 0xE5

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature from HTU21D
int read_temperature(int fd) {
    uint8_t buf[3];
    int result;

    // Send temperature measurement command
    result = write(fd, &HTU21D_TEMP_MEASURE, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (at least 50ms)
    usleep(50000); // 50ms

    // Read 3 bytes of temperature data
    result = read(fd, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = -46.85 + 175.72 * ((float)raw_temp / 65536.0);

    return (int)temperature;
}

// Function to read humidity from HTU21D
int read_humidity(int fd) {
    uint8_t buf[3];
    int result;

    // Send humidity measurement command
    result = write(fd, &HTU21D_HUMID_MEASURE, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing humidity command: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (at least 50ms)
    usleep(50000); // 50ms

    // Read 3 bytes of humidity data
    result = read(fd, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to humidity (%RH)
    int16_t raw_humidity = (buf[0] << 8) | buf[1];
    float humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);

    // Clamp humidity to 0-100%
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;

    return (int)humidity;
}

int main() {
    time_t last_read_time = 0;
    int temperature, humidity;

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("HTU21D sensor reader started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read temperature and humidity
        temperature = read_temperature(i2c_fd);
        humidity = read_humidity(i2c_fd);

        if (temperature == -1 || humidity == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Get current time
        time_t current_time = time(NULL);

        // Check if 60 seconds have passed since the last read
        if (difftime(current_time, last_read_time) >= 60.0) {
            // Print temperature and humidity
            printf("Temperature: %d C, Humidity: %d %%\n", temperature, humidity);

            // Update last read time
            last_read_time = current_time;
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
