#include <errno.h>

// Define GPIO pins
#define GPIO_CHIP 0
#define GPIO_PIN 4
#define GPIO_PIN_2 18

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to set GPIO pin state
int set_gpio_state(int gpio_pin, int state) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO %d: %s\n", gpio_pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

int main() {
    int ret;
    struct gpiod_chip *chip = NULL;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 4 to HIGH
        if (set_gpio_state(GPIO_PIN, 1) != 0) {
            fprintf(stderr, "Error setting GPIO %d to HIGH\n", GPIO_PIN);
        }

        // Set GPIO 18 to LOW
        if (set_gpio_state(GPIO_PIN_2, 0) != 0) {
            fprintf(stderr, "Error setting GPIO %d to LOW\n", GPIO_PIN_2);
        }

        // Wait for 50 milliseconds
        usleep(50000); // 50 milliseconds = 50000 microseconds

        // Set GPIO 4 to LOW
        if (set_gpio_state(GPIO_PIN, 0) != 0) {
            fprintf(stderr, "Error setting GPIO %d to LOW\n", GPIO_PIN);
        }

        // Set GPIO 18 to HIGH
        if (set_gpio_state(GPIO_PIN_2, 1) != 0) {
            fprintf(stderr, "Error setting GPIO %d to HIGH\n", GPIO_PIN_2);
        }

        // Wait for 50 milliseconds
        usleep(50000); // 50 milliseconds = 50000 microseconds
    }

    // The program should never reach here due to the infinite loop.
    // However, this ensures that the GPIO chip is closed if the loop is ever exited.
    gpiod_chip_close(chip);
    return 0;
}

