    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line_gpio = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line_gpio) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get alternative GPIO line
    line_gpio_alt = gpiod_chip_get_line(chip, GPIO_PIN_ALT);
    if (!line_gpio_alt) {
        perror("Error getting alternative GPIO line");
        gpiod_line_release(line_gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_output_test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line_gpio, &config, 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line_gpio_alt);
        gpiod_line_release(line_gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line_gpio_alt, &config, 0) < 0) {
        perror("Error requesting alternative GPIO line for output");
        gpiod_line_release(line_gpio_alt);
        gpiod_line_release(line_gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Set GPIO state
        if (gpiod_line_set_value(line_gpio, 1) < 0) {
            perror("Error setting GPIO value");
            break; // Exit loop on error
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        if (gpiod_line_set_value(line_gpio_alt, 1) < 0) {
            perror("Error setting alternative GPIO value");
            break; // Exit loop on error
        }
        printf("Alternative GPIO %d set HIGH\n", GPIO_PIN_ALT);

        // Sleep for 2 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }

        // Set GPIO state to LOW
        if (gpiod_line_set_value(line_gpio, 0) < 0) {
            perror("Error setting GPIO value");
            break; // Exit loop on error
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        if (gpiod_line_set_value(line_gpio_alt, 0) < 0) {
            perror("Error setting alternative GPIO value");
            break; // Exit loop on error
        }
        printf("Alternative GPIO %d set LOW\n", GPIO_PIN_ALT);
    }

    // Release GPIO lines and close chip
    gpiod_line_release(line_gpio);
    gpiod_line_release(line_gpio_alt);
    gpiod_chip_close(chip);

    printf("GPIO control program finished.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

int i2c_fd = -1; // I2C file descriptor

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an ADXL345 register
int adxl345_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an ADXL345 register
int adxl345_read_register(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345 (set POWER_CTL register to measure mode)
    if (adxl345_write_register(i2c_fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print accelerometer data
    while (1) {
        unsigned char data[6];
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0, &data[0]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 1, &data[1]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 2, &data[2]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 3, &data[3]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 4, &data[4]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 5, &data[5]) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Combine high and low bytes to form 16-bit signed integer
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        // Print the accelerometer data
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        usleep(100000); // 0.1 seconds
    }

    // The program should never reach here due to the infinite loop,
    // but it's good practice to include cleanup code.
    close(i2c_fd);
    return 0;
}

