#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 27
#define NUM_CYCLES 50

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 0.1 seconds

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "my_app", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d (BCM) initialized as output. Starting cycles...\n", GPIO_PIN);

    for (int i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO high
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO high");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Wait 0.1 seconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO low
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO low");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Wait 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        perror("Error closing GPIO chip");
    }

    printf("GPIO control finished.\n");

    return 0;
}

