#include <unistd.h>

// Define GPIO pins
#define GPIO_CHIP 0
#define GPIO_PIN 17
#define GPIO_PIN_2 18

// Global variable to store the GPIO chip handle
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to set the GPIO pin state
int set_gpio_state(int gpio_pin, int state) {
    struct gpiod_line *line = NULL;
    int ret;

    // Open the GPIO line
    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", gpio_pin);
        return -1;
    }

    // Set the GPIO line direction to output
    ret = gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line direction for pin %d\n", gpio_pin);
        gpiod_line_release(line);
        return -1;
    }

    // Set the GPIO line value
    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line value for pin %d\n", gpio_pin);
        gpiod_line_release(line);
        return -1;
    }

    // Close the GPIO line
    gpiod_line_release(line);

    return 0;
}

int main() {
    int state = 0; // Initial state (LOW)
    int new_state = 1; // New state (HIGH)

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set the GPIO state
        if (set_gpio_state(GPIO_PIN, state) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO state\n");
        }

        // Print the current state
        printf("GPIO %d is now %s\n", GPIO_PIN, state ? "HIGH" : "LOW");

        // Toggle the state
        state = !state;
        new_state = !new_state;

        // Set the GPIO state again with the new state
        if (set_gpio_state(GPIO_PIN_2, new_state) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO state\n");
        }

        // Print the new state
        printf("GPIO %d is now %s\n", GPIO_PIN_2, new_state ? "HIGH" : "LOW");

        // Delay for 1 second
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define DHT22_GPIO 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nExiting...\n");
}

int read_dht22_data(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    int i;

    // Send start signal
    gpiod_line_set_value(line, 0); // Low
    usleep(1000); // 1ms
    gpiod_line_set_value(line, 1); // High
    usleep(30); // 30us

    // Receive data
    for (i = 0; i < 40; i++) {
        // Wait for low
        while (gpiod_line_get_value(line) == 1) {
            usleep(1); // Wait 1us
        }

        // Measure high time
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0) {
            usleep(1); // Wait 1us
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        long high_time = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Determine bit value
        if (high_time > 40) {
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main() {
    struct timespec sleep_time = {2, 0}; // 2 seconds
    float temperature, humidity;
    int ret;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_GPIO);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "dht22", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for input");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    printf("DHT22 sensor reading started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        ret = read_dht22_data(DHT22_GPIO, &temperature, &humidity);
        if (ret == 0) {
            printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading DHT22 data\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 17
#define PWM_RANGE 1000
#define PWM_FREQUENCY 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int pwm_value = 0;
    int current_state = 0;
    int previous_state = 0;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as PWM output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    printf("PWM output started on GPIO %d. Press Ctrl+C to exit.\n", PWM_PIN);

    while (!terminate) {
        // Toggle PWM value every 0.5 seconds
        pwm_value = (pwm_value + 500) % PWM_RANGE;

        // Report the current state
        current_state = gpioGetPWMdutycycle(PWM_PIN);
        printf("Current PWM value: %d, Duty Cycle: %d\n", pwm_value, current_state);

        // Set PWM value
        gpioPWM(PWM_PIN, pwm_value);

        // Wait for 0.5 seconds
        gpioDelay(500000); // 0.5 seconds in microseconds
    }

    // Stop PWM output
    gpioPWM(PWM_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"

// Global variable to store the GPIO line
struct gpiod_line *gpio_line = NULL;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    exit(0);
}

// Function to initialize the GPIO line
int initialize_gpio(struct gpiod_line **gpio_line) {
    int ret;
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    *gpio_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!*gpio_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(*gpio_line, "my_gpio", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the GPIO pin state
int set_gpio_state(struct gpiod_line *gpio_line, int state) {
    int ret = gpiod_line_set_value(gpio_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d to state %d: %s\n", GPIO_PIN, state, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO line
    if (initialize_gpio(&gpio_line) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("GPIO %d initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (1) {
        // Set GPIO state to 1
        if (set_gpio_state(gpio_line, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to 1. Exiting.\n", GPIO_PIN);
            break;
        }
        printf("GPIO %d set to 1\n", GPIO_PIN);

        // Set GPIO state to 0
        if (set_gpio_state(gpio_line, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to 0. Exiting.\n", GPIO_PIN);
            break;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    // Close GPIO chip
    gpiod_chip_close(gpiod_chip_open_by_name(GPIO_CHIP));

    return 0;
}

