    // Get second GPIO line
    line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line_2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line_2, "my_app", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_line_release(line);
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Set GPIO 17 HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", GPIO_PIN, strerror(errno));
        } else {
            printf("GPIO %d set HIGH\n", GPIO_PIN);
        }

        // Set GPIO 18 HIGH
        if (gpiod_line_set_value(line_2, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", GPIO_PIN_2, strerror(errno));
        } else {
            printf("GPIO %d set HIGH\n", GPIO_PIN_2);
        }

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                fprintf(stderr, "Error during sleep: %s\n", strerror(errno));
            }
        }

        // Set GPIO 17 LOW
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", GPIO_PIN, strerror(errno));
        } else {
            printf("GPIO %d set LOW\n", GPIO_PIN);
        }

        // Set GPIO 18 LOW
        if (gpiod_line_set_value(line_2, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", GPIO_PIN_2, strerror(errno));
        } else {
            printf("GPIO %d set LOW\n", GPIO_PIN_2);
        }
    }

    // Release GPIO lines
    gpiod_line_release(line);
    gpiod_line_release(line_2);
    gpiod_chip_close(chip);

    printf("GPIO control stopped.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
