#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    config.consumer = "my_gpio_app";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %d\n", GPIO_PIN, ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d requested as output. Value: %s\n", GPIO_PIN, (line->direction == GPIOD_LINE_DIRECTION_OUTPUT) ? "output" : "input");

    // Main loop
    while (keep_running) {
        // Set GPIO value
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO value: %d\n", ret);
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO value: %d\n", ret);
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        // Small delay to prevent busy-waiting
        usleep(100000); // 100ms
    }

    // Release GPIO line
    ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release GPIO line: %d\n", ret);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d control program finished.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

