#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    result = gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO %d, frequency %d Hz, range %d. Press Ctrl+C to exit.\n", PWM_GPIO, PWM_FREQUENCY, PWM_RANGE);

    // Main loop
    while (running) {
        // Set PWM duty cycle (0-1000)
        int duty_cycle = 500; // 50% duty cycle
        gpioPWM(PWM_GPIO, duty_cycle);

        // Print the state
        printf("PWM: %d\n", duty_cycle);

        // Delay for 20 milliseconds
        gpioDelay(20000); // 20 ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

