        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 200000000; // 0.2 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return 1;
    }

    // Set GPIO directions to output
    if (set_gpio_direction(GPIO_PIN_17, "out") < 0 ||
        set_gpio_direction(GPIO_PIN_22, "out") < 0 ||
        set_gpio_direction(GPIO_PIN_23, "out") < 0 ||
        set_gpio_direction(GPIO_PIN_24, "out") < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO values
        if (set_gpio_value(GPIO_PIN_17, 1) < 0 ||
            set_gpio_value(GPIO_PIN_22, 1) < 0 ||
            set_gpio_value(GPIO_PIN_23, 1) < 0 ||
            set_gpio_value(GPIO_PIN_24, 1) < 0) {
            gpiod_chip_close(chip);
            return 1;
        }

        // Sleep for 0.2 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }

        // Set GPIO values to 0
        if (set_gpio_value(GPIO_PIN_17, 0) < 0 ||
            set_gpio_value(GPIO_PIN_22, 0) < 0 ||
            set_gpio_value(GPIO_PIN_23, 0) < 0 ||
            set_gpio_value(GPIO_PIN_24, 0) < 0) {
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // The program should never reach here due to the infinite loop.
    // However, this is good practice for handling errors.
    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_WTIME           (0x03)
#define TCS34725_AILTL           (0x04)
#define TCS34725_AILTH           (0x05)
#define TCS34725_AIHTL           (0x06)
#define TCS34725_AIHTH           (0x07)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)
#define TCS34725_PDATA           (0x1C)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_CONFIG          (0x0E)

// Enable Register Values
#define TCS34725_ENABLE_AIEN     (0x10) // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN      (0x08) // Wait enable - writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN      (0x02) // ALS Enable
#define TCS34725_ENABLE_PON      (0x01) // Power on

// Configuration Register Values
#define TCS34725_CONFIG_AIHTMUP(0x00) // Integration time high byte
#define TCS34725_CONFIG_AIHTL(0x0F)  // Integration time low byte
#define TCS34725_CONFIG_AITMUP(0x00)  // Integration time high byte
#define TCS34725_CONFIG_AITL(0x0F)   // Integration time low byte
#define TCS34725_CONFIG_PERS       (0x00) // Persistance
#define TCS34725_CONFIG_CONTROL(0x01) // Control register

int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to write a byte to a TCS34725 register
int tcs34725_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg | TCS34725_COMMAND_BIT;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from a TCS34725 register
int tcs34725_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg | TCS34725_COMMAND_BIT, 1) != 1) {
        perror("Failed to write to I2C device (read command)");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    uint8_t id;

    // Enable power and ALS
    if (tcs34725_write_reg(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        return -1;
    }
    usleep(3000); // Wait for power-on (3ms)

    // Set integration time (100ms)
    if (tcs34725_write_reg(fd, TCS34725_CONFIG_AIHTMUP, 0x00) < 0) return -1;
    if (tcs34725_write_reg(fd, TCS34725_CONFIG_AIHTL, 0x0F) < 0) return -1;

    // Set gain (1x)
    if (tcs34725_write_reg(fd, TCS34725_CONFIG_CONTROL, 0x00) < 0) return -1;

    // Set persistence (0.5 seconds)
    if (tcs34725_write_reg(fd, TCS34725_CONFIG_PERS, 0x00) < 0) return -1;

    // Verify ID
    if (tcs34725_read_reg(fd, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Failed to read ID register\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect ID: 0x%02X\n", id);
        return -1;
    }

    printf("TCS34725 ID: 0x%02X\n", id);

    return 0;
}

int main() {
    uint8_t clear_data[8];
    uint8_t red_data[8];
    uint8_t green_data[8];
    uint8_t blue_data[8];
    uint8_t clear_value, red_value, green_value, blue_value;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize TCS34725 sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (program_running) {
        // Read clear, red, green, and blue data
        if (tcs34725_read_reg(i2c_fd, TCS34725_CDATA, &clear_value) < 0) {
            fprintf(stderr, "Failed to read clear data\n");
            break;
        }
        if (tcs34725_read_reg(i2c_fd, TCS34725_RDATA, &red_value) < 0) {
            fprintf(stderr, "Failed to read red data\n");
            break;
        }
        if (tcs34725_read_reg(i2c_fd, TCS34725_GDATA, &green_value) < 0) {
            fprintf(stderr, "Failed to read green data\n");
            break;
        }
        if (tcs34725_read_reg(i2c_fd, TCS34725_BDATA, &blue_value) < 0) {
            fprintf(stderr, "Failed to read blue data\n");
            break;
        }

        // Print the data
        printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear_value, red_value, green_value, blue_value);

        // Wait 200ms
        usleep(200000);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_PIN_1 18
#define GPIO_PIN_2 21
#define GPIO_PIN_3 22

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    struct gpiod_line *line_1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    struct gpiod_line *line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    struct gpiod_line *line_3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!line_1 || !line_2 || !line_3) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_1, "output", 0) < 0) {
        perror("Error requesting GPIO line 1 for output");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(line_2, "output", 0) < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(line_3, "output", 0) < 0) {
        perror("Error requesting GPIO line 3 for output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO pin state
int set_gpio_state(int gpio_pin, int state) {
    struct gpiod_line *line = NULL;
    if (gpio_pin == GPIO_PIN_1) {
        line = line_1;
    } else if (gpio_pin == GPIO_PIN_2) {
        line = line_2;
    } else if (gpio_pin == GPIO_PIN_3) {
        line = line_3;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, state) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO pins
int cleanup_gpio() {
    if (chip) {
        gpiod_line_release(line_1);
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        if (set_gpio_state(GPIO_PIN_1, 1) < 0) {
            cleanup_gpio();
            return 1;
        }
        if (set_gpio_state(GPIO_PIN_2, 0) < 0) {
            cleanup_gpio();
            return 1;
        }
        if (set_gpio_state(GPIO_PIN_3, 1) < 0) {
            cleanup_gpio();
            return 1;
        }

        // Print the state applied to each GPIO pin
        printf("GPIO %d: %d\n", GPIO_PIN_1, gpiod_line_get_value(line_1));
        printf("GPIO %d: %d\n", GPIO_PIN_2, gpiod_line_get_value(line_2));
        printf("GPIO %d: %d\n", GPIO_PIN_3, gpiod_line_get_value(line_3));

        // Delay for 1 second
        sleep(1);
    }

    return 0;
}

