    struct v4l2_requestbuffers req;
    unsigned int i;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    buffer_size = req.length * req.count;
    buffer = mmap(NULL, req.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            munmap(buffer, buffer_size);
            return -1;
        }

        buffer_size = buf.length;
        buffer += buf.offset;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(image_t *image) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for a frame to be available (non-blocking)
    int ret = 0;
    while (1) {
        ret = ioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret < 0) {
            if (errno == EAGAIN) {
                // No frame available yet, sleep for a short time
                nanosleep(&(struct timespec){0, 10000000}, NULL); // 10ms
            } else {
                perror("Error dequeuing buffer");
                return -1;
            }
        } else {
            break;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate the time taken to capture the frame
    double time_taken = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    // Copy the frame data to the image buffer
    memcpy(image->data, buffer, image->size);

    return 0;
}

// Function to save the image to a file
int save_image(const char *filename, const image_t *image) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(image->data, 1, image->size, fp);
    if (bytes_written != image->size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, image->size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to uninitialize the video device
void uninit_v4l2() {
    if (fd != -1) {
        ioctl(fd, VIDIOC_STREAMOFF, V4L2_BUF_TYPE_VIDEO_CAPTURE);
        ioctl(fd, VIDIOC_QBUF, V4L2_BUF_TYPE_VIDEO_CAPTURE);
        ioctl(fd, VIDIOC_FREEBUF, V4L2_BUF_TYPE_VIDEO_CAPTURE, buffer);
        munmap(buffer, buffer_size);
        close(fd);
    }
}

int main() {
    image_t image;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the video device
    if (init_v4l2() < 0) {
        fprintf(stderr, "Failed to initialize video device\n");
        return EXIT_FAILURE;
    }

    printf("Video device initialized successfully\n");

    // Capture a single frame and save it to a file
    if (capture_frame(&image) == 0) {
        if (save_image("frame.jpg", &image) == 0) {
            printf("Image saved to frame.jpg\n");
        } else {
            fprintf(stderr, "Failed to save image\n");
        }
    } else {
        fprintf(stderr, "Failed to capture frame\n");
    }

    // Uninitialize the video device
    uninit_v4l2();

    printf("Video device uninitilized\n");

    return EXIT_SUCCESS;
}

