// SSD1306 I2C address
#define SSD1306_I2C_ADDR 0x3C

// SSD1306 screen dimensions
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

// I2C file descriptor
int i2c_fd;

// Flag to indicate program should exit
volatile sig_atomic_t program_running = 1;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to write a command to the SSD1306
int ssd1306_command(unsigned char command) {
    unsigned char buffer[2];
    buffer[0] = 0x00; // Control byte: command
    buffer[1] = command;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write command to SSD1306");
        return -1;
    }
    return 0;
}

// Function to write data to the SSD1306
int ssd1306_data(unsigned char data) {
    unsigned char buffer[2];
    buffer[0] = 0x40; // Control byte: data
    buffer[1] = data;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write data to SSD1306");
        return -1;
    }
    return 0;
}

// Function to initialize the SSD1306
int ssd1306_init() {
    // Initialization sequence (example)
    if (ssd1306_command(0xAE) != 0) return -1; // Display off
    if (ssd1306_command(0xD5) != 0) return -1; // Set display clock divide ratio/oscillator frequency
    if (ssd1306_command(0x80) != 0) return -1; // --ratio
    if (ssd1306_command(0xA8) != 0) return -1; // Set multiplex ratio
    if (ssd1306_command(0x3F) != 0) return -1; // --height-1
    if (ssd1306_command(0xD3) != 0) return -1; // Set display offset
    if (ssd1306_command(0x00) != 0) return -1; // --offset
    if (ssd1306_command(0x40) != 0) return -1; // Set start line address
    if (ssd1306_command(0x8D) != 0) return -1; // Charge pump setting
    if (ssd1306_command(0x14) != 0) return -1; // --enable
    if (ssd1306_command(0x20) != 0) return -1; // Set memory addressing mode
    if (ssd1306_command(0x00) != 0) return -1; // --horizontal addressing mode
    if (ssd1306_command(0xA1) != 0) return -1; // Set segment re-map
    if (ssd1306_command(0xC8) != 0) return -1; // Set COM output scan direction
    if (ssd1306_command(0xDA) != 0) return -1; // Set COM pins hardware configuration
    if (ssd1306_command(0x12) != 0) return -1; // --alternative
    if (ssd1306_command(0x81) != 0) return -1; // Set contrast control
    if (ssd1306_command(0xCF) != 0) return -1; // --contrast
    if (ssd1306_command(0xD9) != 0) return -1; // Set pre-charge period
    if (ssd1306_command(0xF1) != 0) return -1; // --period
    if (ssd1306_command(0xDB) != 0) return -1; // Set VCOM deselect level
    if (ssd1306_command(0x40) != 0) return -1; // --level
    if (ssd1306_command(0xA4) != 0) return -1; // Entire display ON/OFF
    if (ssd1306_command(0xA6) != 0) return -1; // Set normal display
    if (ssd1306_command(0xAF) != 0) return -1; // Display on

    return 0;
}

// Function to clear the display
int ssd1306_clear() {
    for (int i = 0; i < SSD1306_WIDTH * (SSD1306_HEIGHT / 8); i++) {
        if (ssd1306_data(0x00) != 0) return -1; // Write 0 to all pixels
    }
    return 0;
}

// Function to display a string at a specific position
int ssd1306_display_string(int x, int y, const char *str) {
    // Simple character mapping (ASCII 32-126) to a font (example)
    // This is a placeholder; a real implementation would use a font table
    // and render each character.

    // For simplicity, we'll just print the ASCII values as is.
    // This is not a proper font rendering, but it demonstrates the concept.

    unsigned char font_data[6] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00}; // Example font data for 'A'
    for (int i = 0; str[i] != '\0'; i++) {
        // Calculate the starting column and row
        int col = x + i; // Character position
        int row = y;       // Row position

        // Send column address
        if (ssd1306_command(0x21) != 0) return -1; // Column address
        if (ssd1306_command(col) != 0) return -1; // Column address

        // Send page address
        if (ssd1306_command(0x22) != 0) return -1; // Page address
        if (ssd1306_command(y / 8) != 0) return -1; // Page address

        // Send font data
        if (ssd1306_data(font_data[0]) != 0) return -1; // Font data
        if (ssd1306_data(font_data[1]) != 0) return -1; // Font data
        if (ssd1306_data(font_data[2]) != 0) return -1; // Font data
        if (ssd1306_data(font_data[3]) != 0) return -1; // Font data
        if (ssd1306_data(font_data[4]) != 0) return -1; // Font data
        if (ssd1306_data(font_data[5]) != 0) return -1; // Font data

    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
