    if (ret < 0) {
        fprintf(stderr, "Error: Could not request echo2 line %d for input: %s\n", ECHO2_PIN, strerror(-ret));
        gpiod_line_release(*trigger);
        gpiod_line_release(*echo);
        gpiod_line_release(*echo2);
        return -1;
    }

    return 0;
}

// Generate a 10us trigger pulse
int trigger_pulse(struct gpiod_line *trigger) {
    int ret;
    ret = gpiod_line_set_value(trigger, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set trigger value: %s\n", strerror(-ret));
        return -1;
    }
    usleep(10); // 10us
    ret = gpiod_line_set_value(trigger, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set trigger value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Read the echo pulse duration
int read_pulse(struct gpiod_line *echo, struct gpiod_line *echo2) {
    struct timespec start, end;
    int ret;
    long long duration;

    ret = clock_gettime(CLOCK_MONOTONIC, &start);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get start time: %s\n", strerror(-ret));
        return -1;
    }

    while (gpiod_line_get_value(echo) == 0) {
        ret = clock_gettime(CLOCK_MONOTONIC, &end);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not get end time: %s\n", strerror(-ret));
            return -1;
        }
        if ((end.tv_sec - start.tv_sec) * 1000000LL + (end.tv_nsec - start.tv_nsec) / 1000 > 10000000) {
            fprintf(stderr, "Error: Timeout waiting for echo start\n");
            return -1;
        }
    }

    ret = clock_gettime(CLOCK_MONOTONIC, &end);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get end time: %s\n", strerror(-ret));
        return -1;
    }

    duration = (end.tv_sec - start.tv_sec) * 1000000LL + (end.tv_nsec - start.tv_nsec) / 1000;

    return duration;
}

// Cleanup GPIO lines
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *trigger, struct gpiod_line *echo, struct gpiod_line *echo2) {
    if (trigger) {
        gpiod_line_release(trigger);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (echo2) {
        gpiod_line_release(echo2);
    }
}

