    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from the MPU6050
int read_mpu6050(int fd, unsigned char reg) {
    unsigned char buffer[1];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (read(fd, buffer, 1) != 1) {
            perror("Failed to read data");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        return buffer[0];
    }

    fprintf(stderr, "Failed to read from MPU6050 after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to read accelerometer data from MPU6050
int read_accelerometer_data(int fd, int *x, int *y, int *z) {
    int x_h, x_l, y_h, y_l, z_h, z_l;

    x_h = read_mpu6050(fd, ACCEL_XOUT_H);
    x_l = read_mpu6050(fd, ACCEL_XOUT_H + 1);
    y_h = read_mpu6050(fd, ACCEL_XOUT_H + 2);
    y_l = read_mpu6050(fd, ACCEL_XOUT_H + 3);
    z_h = read_mpu6050(fd, ACCEL_XOUT_H + 4);
    z_l = read_mpu6050(fd, ACCEL_XOUT_H + 5);

    if (x_h == -1 || x_l == -1 || y_h == -1 || y_l == -1 || z_h == -1 || z_l == -1) {
        fprintf(stderr, "Error reading accelerometer data.\n");
        return -1; // Indicate failure
    }

    *x = (x_h << 8) | x_l;
    *y = (y_h << 8) | y_l;
    *z = (z_h << 8) | z_l;

    return 0; // Indicate success
}

int main() {
    int x, y, z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 milliseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (write(i2c_fd, &PWR_MGMT_1, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1 register");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
