// Function to read a single byte from an I2C register
int read_register(int fd, unsigned char reg) {
    unsigned char buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return buf[0];
}

// Function to write a single byte to an I2C register
int write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (write_register(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Read 100 accelerometer readings
    for (int i = 0; i < 100; i++) {
        // Read accelerometer data
        int high_byte = read_register(i2c_fd, ACCEL_XOUT_H);
        int low_byte = read_register(i2c_fd, ACCEL_XOUT_H + 1);

        if (high_byte < 0 || low_byte < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            close(i2c_fd);
            return 1;
        }

        // Combine high and low bytes to form a 16-bit value
        int16_t accel_x = (high_byte << 8) | low_byte;

        // Print the reading
        printf("Reading %d: %d\n", i + 1, accel_x);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

