long read_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;
    int ret;

    // Wait for echo to go high
    do {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            perror("Error getting echo line value");
            return -1;
        }
        if (ret) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            break;
        }
    } while (1);

    // Wait for echo to go low
    do {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            perror("Error getting echo line value");
            return -1;
        }
        if (!ret) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            break;
        }
    } while (1);

    // Calculate pulse width
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec) / 1000LL;

    return pulse_width;
}

// Calculate distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SOUND_SPEED / 2.0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    int ret;

    // Release trigger line
    ret = gpiod_line_release(trigger_line);
    if (ret < 0) {
        perror("Error releasing trigger line");
    }

    // Release echo line
    ret = gpiod_line_release(echo_line);
    if (ret < 0) {
        perror("Error releasing echo line");
    }

    // Close GPIO chip
    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        perror("Error closing GPIO chip");
    }
}

int main(void) {
    int ret;
    long pulse_width;
    float distance;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Trigger pulse
        if (trigger_pulse() < 0) {
            fprintf(stderr, "Error sending trigger pulse. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Read pulse width
        pulse_width = read_pulse_width();
        if (pulse_width < 0) {
            fprintf(stderr, "Error reading pulse width. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate distance
        distance = calculate_distance(pulse_width);

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Wait 100ms
        usleep(100000); // 100ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

