#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    config.consumer = "my_gpio_app";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (keep_running) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break; // Exit loop on error
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Wait for 1 second
        sleep(1);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break; // Exit loop on error
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO line
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d (BCM) released. Exiting.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

