#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_23 23

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Function to set GPIO direction
int set_gpio_direction(int gpio, const char *direction) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set direction for GPIO %d: %s\n", gpio, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

// Function to write value to GPIO
int write_gpio_value(int gpio, int value) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO %d: %s\n", gpio, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    int value = 1; // Initial value

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Set GPIO directions
    if (set_gpio_direction(GPIO_PIN_1, "out") < 0) {
        gpiod_chip_close(chip);
        return 1;
    }
    if (set_gpio_direction(GPIO_PIN_2, "out") < 0) {
        gpiod_chip_close(chip);
        return 1;
    }
    if (set_gpio_direction(GPIO_PIN_23, "out") < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Write value to GPIO 2
        if (write_gpio_value(GPIO_PIN_1, value) < 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", GPIO_PIN_1);
        }

        // Write value to GPIO 3
        if (write_gpio_value(GPIO_PIN_2, value) < 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", GPIO_PIN_2);
        }

        // Write value to GPIO 23
        if (write_gpio_value(GPIO_PIN_23, value) < 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", GPIO_PIN_23);
        }

        // Print the current state
        printf("GPIO 2: %s, GPIO 3: %s, GPIO 23: %s\n",
               (value == 1) ? "HIGH" : "LOW",
               (value == 1) ? "HIGH" : "LOW",
               (value == 1) ? "HIGH" : "LOW");

        // Toggle the value
        value = !value;

        // Wait for 2 seconds
        usleep(2000000); // 2 seconds = 2000000 microseconds
    }

    // The program should never reach here due to the infinite loop.
    // However, this ensures that the GPIO chip is closed if the loop is ever exited.
    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "wearable/sensor_data"
#define SENSOR_GPIO 4 // GPIO pin connected to the sensor

// Global variables for cleanup
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_sensor_data();
int publish_sensor_data(int sensor_value);
void signal_handler(int signum);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, cleaning up and exiting...\n");
        running = 0;
    }
}

// Function to read sensor data from GPIO pin
int read_sensor_data() {
    int sensor_value = gpioRead(SENSOR_GPIO);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", sensor_value);
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to publish sensor data to MQTT broker
int publish_sensor_data(int sensor_value) {
    char payload[10];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1; // Indicate error
    }
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Initialize MQTT library
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read and publish sensor data
    while (running) {
        int sensor_value = read_sensor_data();
        if (sensor_value >= 0) {
            if (publish_sensor_data(sensor_value) != 0) {
                fprintf(stderr, "Error publishing data, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor, but continuing...\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int pwm_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as PWM output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO %d, frequency %d Hz, range %d. Press Ctrl+C to exit.\n", PWM_GPIO, PWM_FREQUENCY, PWM_RANGE);

    while (running) {
        // Generate PWM values (0-1000) and output them
        for (pwm_value = 0; pwm_value <= 1000; pwm_value++) {
            gpioPWM(PWM_GPIO, pwm_value);
            printf("PWM value: %d\n", pwm_value);
            usleep(100000); // 100ms delay
        }

        // Generate PWM values (1000-0) and output them
        for (pwm_value = 1000; pwm_value >= 0; pwm_value--) {
            gpioPWM(PWM_GPIO, pwm_value);
            printf("PWM value: %d\n", pwm_value);
            usleep(100000); // 100ms delay
        }
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define distance threshold (in cm)
#define DISTANCE_THRESHOLD 30.0

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
void trigger_pulse(void);
long long echo_time(void);
double calculate_distance(long long time);
void report_state(double distance);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line for output
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        perror("Error requesting trigger line for output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line for input
    ret = gpiod_line_request_input(echo_line, "echo", 0);
    if (ret < 0) {
        perror("Error requesting echo line for input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse(void) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "trigger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        perror("Error requesting trigger line for output");
        return;
    }

    // Wait for 10us
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10000; // 10us
    nanosleep(&ts, NULL);

    // Release the line
    ret = gpiod_line_release(trigger_line);
    if (ret < 0) {
        perror("Error releasing trigger line");
    }
}

// Measure echo pulse width
long long echo_time(void) {
    struct timespec start, end;
    long long pulse_width = 0;

    // Wait for echo to go high
    do {
        clock_gettime(CLOCK_MONOTONIC, &start);
        if (gpiod_line_get_value(echo_line) == 1) {
            break;
        }
        // Wait for a maximum time, e.g., 100ms
        struct timespec max_wait;
        max_wait.tv_sec = 0;
        max_wait.tv_nsec = 100000000; // 100ms
        nanosleep(&max_wait, NULL);
    } while (1);

    if (!gpiod_line_get_value(echo_line)) {
        fprintf(stderr, "Error: Echo line did not go high\n");
        return -1;
    }

    // Wait for echo to go low
    do {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (gpiod_line_get_value(echo_line) == 0) {
            break;
        }
        // Wait for a maximum time, e.g., 100ms
        struct timespec max_wait;
        max_wait.tv_sec = 0;
        max_wait.tv_nsec = 100000000; // 100ms
        nanosleep(&max_wait, NULL);
    } while (1);

    if (!gpiod_line_get_value(echo_line)) {
        fprintf(stderr, "Error: Echo line did not go low\n");
        return -1;
    }

    // Calculate pulse width
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(long long time) {
    return (double)time / 1000000000.0 * 34300.0 / 2.0; // Speed of sound: 343 m/s
}

// Report the distance
void report_state(double distance) {
    printf("Distance: %.2f cm\n", distance);
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int ret;
    double distance;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_pulse();
        long long pulse_width = echo_time();

        if (pulse_width > 0) {
            distance = calculate_distance(pulse_width);
            report_state(distance);
            if (distance < DISTANCE_THRESHOLD) {
                printf("Object detected within threshold!\n");
            }
        } else {
            fprintf(stderr, "Error: Echo time measurement failed\n");
        }

        usleep(200000); // 200ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    int pwm_value = (int)((duty_cycle / PWM_RANGE) * 1000.0);
    gpioPWM(gpio_pin, pwm_value);
    printf("GPIO %d: Duty cycle = %d, PWM value = %d\n", gpio_pin, duty_cycle, pwm_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency for each pin
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);

    // Set PWM range for each pin
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);

