        set_pwm_duty_cycle(PWM_PIN_2, 250);
        set_pwm_duty_cycle(PWM_PIN_3, 750);
        set_pwm_duty_cycle(PWM_PIN_4, 750);

        // Delay for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
