#define DEVICE_GPIO 4
#define MQTT_TOPIC "agriculture/sensor_data"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_agri_sensor"
#define MQTT_KEEPALIVE 60
#define MQTT_MAX_MESSAGE_SIZE 256

// Global variables for cleanup
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_device_data();
int validate_reading(int reading);
int publish_reading(int reading);
void signal_handler(int signum);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

// Function to read data from the connected device
int read_device_data() {
    int reading = gpioRead(DEVICE_GPIO);
    if (reading < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", DEVICE_GPIO, reading);
        return -1; // Indicate an error
    }
    return reading;
}

// Function to validate the sensor reading
int validate_reading(int reading) {
    if (reading >= 0 && reading <= 1023) {
        return 1; // Valid reading
    } else {
        fprintf(stderr, "Invalid reading: %d\n", reading);
        return 0; // Invalid reading
    }
}

// Function to publish the sensor reading to MQTT
int publish_reading(int reading) {
    char payload[10];
    snprintf(payload, sizeof(payload), "%d", reading);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1; // Indicate an error
    }
    return 0; // Success
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as input
    gpioSetMode(DEVICE_GPIO, PI_INPUT);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set callback for connection
    mosquitto_connect_callback_set(mosq, NULL, NULL, NULL);

    // Set callback for message arrival
    mosquitto_message_callback_set(mosq, on_message);

    // Subscribe to the topic
    ret = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing to topic: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read, validate, and publish data
    while (running) {
        int reading = read_device_data();
        if (reading >= 0) {
            if (validate_reading(reading)) {
                if (publish_reading(reading) != 0) {
                    fprintf(stderr, "Error publishing reading\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading device data, retrying...\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    // This function is called when a message is received.
    // Since we are only publishing, we don't need to handle incoming messages.
    (void)mosq;
    (void)userdata;
    (void)message;
}

