// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define VREF 4.096
#define NUM_READINGS 10
#define MQTT_TOPIC "agriculture/sensor_data"
#define MQTT_QOS 1
#define MQTT_KEEPALIVE 60

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_ads1115();
int read_ads1115(float *value);
int publish_mqtt(float value);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115
int config_ads1115() {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = 0xC2; // Single-shot mode, +/-4.096V, 128 SPS, Disable comparator
    buf[2] = 0x83; // Start single conversion

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115\n");
        return -1;
    }
    return 0;
}

// Read ADS1115
int read_ads1115(float *value) {
    char buf[1];
    char read_buf[2];
    int16_t raw_value;

    buf[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to ADS1115 for read\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115\n");
        return -1;
    }

    raw_value = (read_buf[0] << 8) | read_buf[1];

    *value = (float)raw_value * VREF / 32768.0;

    return 0;
}

// Publish MQTT
int publish_mqtt(float value) {
    char payload[20];
    int ret;

    snprintf(payload, sizeof(payload), "%.3f", value);

    ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, MQTT_QOS, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing MQTT: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    float sensor_value;
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (config_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mosquitto_connect(mosq, "localhost", 1883, MQTT_KEEPALIVE) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    for (int i = 0; i < NUM_READINGS && !terminate; ++i) {
        if (read_ads1115(&sensor_value) == 0) {
            printf("Sensor value: %.3f\n", sensor_value);
            if (publish_mqtt(sensor_value) != 0) {
                fprintf(stderr, "Error publishing MQTT, exiting\n");
                break;
            }
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
        }
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

