#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int setup_uart(const char *device, speed_t baud_rate) {
    int uart_fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 5;                             // 0.5 seconds read timeout

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return -1;
    }

    return uart_fd;
}

int read_uart(int uart_fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(uart_fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // No data available
        }
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[BUFFER_SIZE];
    fd_set readfds;
    struct timeval timeout;

    printf("Starting UART communication...\n");

    while (program_running) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = 1;  // Timeout after 1 second
        timeout.tv_usec = 0;

        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("Error in select");
            break;
        } else if (select_result == 0) {
            // Timeout occurred, no data available
            continue;
        } else {
            // Data is available
            int bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
            if (bytes_read > 0) {
                buffer[bytes_read] = '\0';
                printf("Received: %s\n", buffer);
            } else if (bytes_read == -1) {
                // Error reading from UART, exit loop
                break;
            }
        }
    }

    close(uart_fd);
    printf("UART communication stopped.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from the MPU6050
int read_mpu6050(int fd, unsigned char reg) {
    unsigned char buffer[1];
    int result;

    result = write(fd, &reg, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    result = read(fd, buffer, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return buffer[0];
}

// Function to read accelerometer data from the MPU6050
int read_accelerometer_data(int fd, int *x, int *y, int *z) {
    int x_high, x_low, y_high, y_low, z_high, z_low;

    x_high = read_mpu6050(fd, ACCEL_XOUT_H);
    x_low  = read_mpu6050(fd, ACCEL_XOUT_H + 1);
    y_high = read_mpu6050(fd, ACCEL_XOUT_H + 2);
    y_low  = read_mpu6050(fd, ACCEL_XOUT_H + 3);
    z_high = read_mpu6050(fd, ACCEL_XOUT_H + 4);
    z_low  = read_mpu6050(fd, ACCEL_XOUT_H + 5);

    if (x_high == -1 || x_low == -1 || y_high == -1 || y_low == -1 || z_high == -1 || z_low == -1) {
        return -1; // Indicate error
    }

    *x = (x_high << 8) | x_low;
    *y = (y_high << 8) | y_low;
    *z = (z_high << 8) | z_low;

    return 0; // Indicate success
}

int main() {
    int x, y, z;
    struct timespec sleep_time;
    int retries = 3; // Number of retries for I2C communication

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    while (retries > 0) {
        if (write(i2c_fd, &PWR_MGMT_1, 1) == 1) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing to PWR_MGMT_1 register (attempt %d): %s\n", 4 - retries, strerror(errno));
            retries--;
            nanosleep(&(struct timespec){0, 10000000}, NULL); // Wait 10ms before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to wake up MPU6050 after multiple retries.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 reader started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Print the data
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Error reading accelerometer data.\n");
        }

        // Sleep for 100 milliseconds
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
