#include <string.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from the BMP280
int read_bmp280_register(int fd, uint8_t reg_addr, uint8_t *data) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// Function to write a single byte to the BMP280
int write_bmp280_register(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(int fd, uint16_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3, uint16_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3, int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6, int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9) {
    uint8_t data[26];
    if (read_bmp280_register(fd, BMP280_REG_CALIB_00, &data[0]) != 0) return -1;
    *dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    *dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    *dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    *dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    *dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    *dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    *dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    *dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    *dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    *dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    *dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    *dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read temperature and pressure from the BMP280
int read_bmp280_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t raw_temp, raw_press;
    int32_t var1, var2, T, p;
    int32_t dig_T1, dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

    // Set the BMP280 to forced mode
    if (write_bmp280_register(fd, BMP280_REG_CTRL_MEAS, 0b00100111) != 0) {
        perror("Failed to set forced mode");
        return -1;
    }

    // Wait for the measurement to complete (adjust delay as needed)
    usleep(10000); // 10ms

    // Read the raw temperature and pressure data
    if (read_bmp280_register(fd, BMP280_REG_PRESS_MSB, &data[0]) != 0) return -1;
    raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    if (read_bmp280_register(fd, BMP280_REG_TEMP_MSB, &data[0]) != 0) return -1;
    raw_temp = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);

    // Read calibration data
    if (read_calibration_data(fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9) != 0) {
        perror("Failed to read calibration data");
        return -1;
    }

    // Temperature compensation
    var1 = ((((raw_temp >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)dig_T1)) * ((raw_temp >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    T = var1 + var2;
    float t_fine = (T * 5 + 128) >> 8;
    *temperature = (t_fine * 5 + 128) >> 8;
    *temperature = *temperature / 100.0;

    // Pressure compensation
    var1 = ((int32_t)t_fine) - 128000;
    var2 = var1 * var1 * (int32_t)dig_P6;
    var2 = var2 + ((var1 * (int32_t)dig_P5) << 17);
    var2 = var2 + (((int32_t)dig_P4) << 35);
    var1 = ((var1 * var1 * (int32_t)dig_P3) >> 8) + ((var1 * (int32_t)dig_P2) << 12);
    var1 = (((((int32_t)1) << 47) + var1)) * ((int32_t)dig_P1) >> 33;

    if (var1 == 0) {
        return 0; // avoid exception caused by division by zero
    }
    p = 1048576 - raw_press;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int32_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int32_t)dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int32_t)dig_P7) << 4);
    *pressure = (float)p / 256.0;

    return 0;
}

int main() {
    float temperature, pressure;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    printf("BMP280 reader started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read temperature and pressure
        if (read_bmp280_data(i2c_fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read BMP280 data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device (this part will not be reached in the infinite loop)
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 4
#define PWM_FREQUENCY 1000

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-1000000)
    result = gpioSetPWMrange(PWM_GPIO, 1000000);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO %d, frequency %d Hz. Press Ctrl+C to exit.\n", PWM_GPIO, PWM_FREQUENCY);

    // Main loop
    while (running) {
        // Generate PWM signal (50% duty cycle)
        gpioPWM(PWM_GPIO, 500000);

        // Print the state
        printf("GPIO %d: %d\n", PWM_GPIO, gpioGetPWMdutycycle(PWM_GPIO));

        // Delay for 1 second
        gpioDelay(1000000);
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_CHIP 0
#define GPIO_NUM 0 // GPIO 5 (BCM numbering)

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio_line;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize GPIO line
int initialize_gpio(struct gpiod_chip *chip, int gpio_num);

// Function to set GPIO direction (in or out)
int set_gpio_direction(struct gpiod_line *line, const char *direction);

// Function to set GPIO value (0 or 1)
int set_gpio_value(struct gpiod_line *line, int value);

// Function to cleanup GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Initialize GPIO line
    if (initialize_gpio(chip, GPIO_NUM) != 0) {
        fprintf(stderr, "Error initializing GPIO %d\n", GPIO_NUM);
        cleanup_gpio(chip, NULL);
        return EXIT_FAILURE;
    }

    // Set GPIO direction to output
    if (set_gpio_direction(gpio_line, "out") != 0) {
        fprintf(stderr, "Error setting GPIO %d direction to output\n", GPIO_NUM);
        cleanup_gpio(chip, gpio_line);
        return EXIT_FAILURE;
    }

    // Main loop to toggle GPIO state
    while (1) {
        // Set GPIO value to 1
        if (set_gpio_value(gpio_line, 1) != 0) {
            fprintf(stderr, "Error setting GPIO %d value to 1\n", GPIO_NUM);
            cleanup_gpio(chip, gpio_line);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to 1\n", GPIO_NUM);

        // Wait for 1 second
        sleep(1);

        // Set GPIO value to 0
        if (set_gpio_value(gpio_line, 0) != 0) {
            fprintf(stderr, "Error setting GPIO %d value to 0\n", GPIO_NUM);
            cleanup_gpio(chip, gpio_line);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to 0\n", GPIO_NUM);

        // Wait for 1 second
        sleep(1);
    }

    return EXIT_SUCCESS;
}

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, gpio_line);
    exit(0);
}

// Function to initialize GPIO line
int initialize_gpio(struct gpiod_chip *chip, int gpio_num) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_num);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_request(line, "my_gpio", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) != 0) {
        perror("Error requesting GPIO line");
        return -1;
    }

    return 0;
}

// Function to set GPIO direction (in or out)
int set_gpio_direction(struct gpiod_line *line, const char *direction) {
    if (gpiod_line_set_direction(line, direction) != 0) {
        perror("Error setting GPIO direction");
        return -1;
    }
    return 0;
}

// Function to set GPIO value (0 or 1)
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) != 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "wearable/sensor_data"
#define SENSOR_PIN 4 // GPIO pin connected to the sensor

// Global variables for cleanup
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_sensor();
int publish_message(const char *message);
void signal_handler(int signum);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, cleaning up and exiting...\n");
        running = 0;
    }
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to publish the sensor reading to MQTT
int publish_message(const char *message) {
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(message), message, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read sensor and publish data
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) {
            char message[10];
            snprintf(message, sizeof(message), "%d", sensor_value);
            if (publish_message(message) != 0) {
                fprintf(stderr, "Failed to publish message.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor value.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_PIN_4 23
#define PWM_PIN_5 24

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping PWM and exiting...\n", signal);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    int pwm_value = (int)((duty_cycle / PWM_RANGE) * 1000.0);
    gpioPWM(gpio, pwm_value);
    printf("GPIO %d: Duty cycle = %d (PWM value = %d)\n", gpio, duty_cycle, pwm_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_5, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Example: Set duty cycles for each PWM pin
        set_pwm_duty_cycle(PWM_PIN_1, 500);
        set_pwm_duty_cycle(PWM_PIN_2, 750);
        set_pwm_duty_cycle(PWM_PIN_3, 250);
        set_pwm_duty_cycle(PWM_PIN_4, 750);
        set_pwm_duty_cycle(PWM_PIN_5, 750);

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM and terminate pigpio
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_5, 0);

    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN 17
#define ENABLE_PIN 22
#define CS_PIN 27

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 50

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_spi();
void set_pwm(int duty_cycle);
void enable_pwm();
void disable_pwm();
void disable_spi();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);

    gpioPWM(PWM_PIN, 0); // Initialize PWM to 0
    gpioWrite(ENABLE_PIN, 1); // Enable PWM initially
    gpioWrite(CS_PIN, 1); // Chip Select High initially

    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Set PWM duty cycle
void set_pwm(int duty_cycle) {
    gpioPWM(PWM_PIN, duty_cycle);
}

// Enable PWM
void enable_pwm() {
    gpioWrite(ENABLE_PIN, 0); // Enable PWM
}

// Disable PWM
void disable_pwm() {
    gpioWrite(ENABLE_PIN, 1); // Disable PWM
}

// Disable SPI
void disable_spi() {
    spiClose(spi_handle);
}

// Cleanup resources before exiting
void cleanup() {
    disable_pwm(); // Ensure PWM is disabled
    disable_spi(); // Ensure SPI is disabled
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi()) {
        cleanup();
        return 1;
    }

    printf("PWM and SPI control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Enable PWM
        enable_pwm();

        // Set PWM duty cycle
        set_pwm(PWM_DUTY_CYCLE);

        // Enable SPI
        gpioWrite(CS_PIN, 0); // Chip Select Low
        spiXfer(spi_handle, NULL, NULL, 0); // Dummy SPI transfer
        gpioWrite(CS_PIN, 1); // Chip Select High

        // Disable PWM and SPI
        disable_pwm();
        disable_spi();

        // Wait for 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3)
#define DEVICE_NAME_LENGTH 256

static volatile int keep_running = 1;
static int fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int n_buffers;
    struct v4l2_buffer buf;
    struct v4l2_control ctrl;
    unsigned char *image_data = NULL;
    FILE *fp;
    int i;
    time_t start_time, current_time;
    double elapsed_time;
    char filename[256];

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer for simplicity
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctrl.c = 0; // Stream 0
    ctrl.m.offset = 0;

    if (ioctl(fd, VIDIOC_STREAMON, &ctrl) < 0) {
        perror("Error starting stream");
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Streaming started. Press Ctrl+C to stop.\n");

    while (keep_running) {
        // Capture image
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break;
        }

        // Save image to file
        image_data = (unsigned char *)buffer;
        fp = fopen("image.rgb", "wb");
        if (fp == NULL) {
            perror("Error opening file");
            break;
        }

        for (i = 0; i < IMAGE_SIZE; i++) {
            fwrite(&image_data[i], 1, 1, fp);
        }

        fclose(fp);

        // Requeue buffer
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            break;
        }

        // Get current time
        time(&start_time);

        // Wait for 1 second
        while (keep_running && (time(NULL) - start_time) < 1) {
            usleep(100000); // Sleep for 100ms
        }

        // Get current time
        time(&current_time);

        // Calculate elapsed time
        elapsed_time = difftime(current_time, start_time);

        // Print elapsed time
        printf("Elapsed time: %.2f seconds\n", elapsed_time);

        // Check for interrupt signal
        if (keep_running) {
            if (signal(SIGINT, signal_handler) == SIG_ERR) {
                perror("Error reinstalling signal handler");
                break;
            }
        }
    }

    // Stop streaming
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctrl.c = 0; // Stream 0
    ctrl.m.offset = 0;

    if (ioctl(fd, VIDIOC_STREAMOFF, &ctrl) < 0) {
        perror("Error stopping stream");
    }

    // Unmap buffer
    if (munmap(buffer, buffer_size) < 0) {
        perror("Error unmapping buffer");
    }

    // Close device
    if (close(fd) < 0) {
        perror("Error closing device");
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

