#define I2C_ADDRESS 0x48
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_MJPEG

static int fd = -1; // File descriptor for the camera device
static void *buffer = NULL; // Pointer to the camera buffer
static unsigned int buffer_size = 0; // Size of the camera buffer
static int i2c_fd = -1; // File descriptor for the I2C device
static int i2c_address = I2C_ADDRESS; // I2C address of the sensor
