    // to trigger a measurement, then read the result.

    // Dummy sensor data for demonstration
    data->temperature = 25 + (rand() % 10); // Temperature between 25 and 35
    data->humidity = 60 + (rand() % 20);    // Humidity between 60 and 80

    return 0;
}

// Capture an image from the camera
int capture_image(int fd, void *buffer, unsigned int buffer_size, const char *filename) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (write(filename, buffer, buffer_size) != buffer_size) {
        perror("Error writing image to file");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Save the captured image to a file
int save_image(const char *filename, const void *buffer, unsigned int buffer_size) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, 1, buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %u\n", bytes_written, buffer_size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup(void) {
    if (fd != -1) {
        if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("Error stopping stream");
        }
        if (munmap(buffer, buffer_size) < 0) {
            perror("Error unmapping buffer");
        }
        close(fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main(void) {
    sensor_data_t sensor_data;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize camera
    if (init_camera() < 0) {
        fprintf(stderr, "Camera initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Camera initialized. Capturing image...\n");

    // Capture image
    if (capture_image(fd, buffer, buffer_size, "image.jpg") < 0) {
        fprintf(stderr, "Image capture failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Image captured and saved as image.jpg\n");

    // Read sensor data
    if (read_sensor_data(&sensor_data) < 0) {
        fprintf(stderr, "Failed to read sensor data. Continuing without sensor data.\n");
    } else {
        printf("Temperature: %d°C, Humidity: %d%%\n", sensor_data.temperature, sensor_data.humidity);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_PIN_ALT 3
#define GPIO_LINE "out"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct timespec sleep_time = {0, 500000000}; // 0.5 seconds
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request;
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "my_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    request = gpiod_line_request(line, &config, 0);
    if (!request) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO state
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value to 1: %s\n", strerror(errno));
            gpiod_line_release(request);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        nanosleep(&sleep_time, NULL);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value to 0: %s\n", strerror(errno));
            gpiod_line_release(request);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Release GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO27 27

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line27;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec sleep_time = {1, 0}; // 1 second
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line handles for GPIO 17 and GPIO 27
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("Error getting line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line27) {
        perror("Error getting line 27");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO 17 as output
    ret = gpiod_line_request_output(line17, "my_app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 17 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO 27 as output
    ret = gpiod_line_request_output(line27, "my_app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 27 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        // Set GPIO 17 HIGH
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 HIGH");
        } else {
            printf("GPIO 17 set HIGH\n");
        }

        // Set GPIO 27 HIGH
        ret = gpiod_line_set_value(line27, 1);
        if (ret < 0) {
            perror("Error setting GPIO 27 HIGH");
        } else {
            printf("GPIO 27 set HIGH\n");
        }

        // Wait for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }

        // Set GPIO 17 LOW
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 LOW");
        } else {
            printf("GPIO 17 set LOW\n");
        }

        // Set GPIO 27 LOW
        ret = gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            perror("Error setting GPIO 27 LOW");
        } else {
            printf("GPIO 27 set LOW\n");
        }
    }

    // Release GPIO lines and chip
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    printf("GPIO control stopped.\n");

    return 0;
}

#include <stdio.h>
