#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIOCHIP "gpiochip0"
#define GPIO18 18
#define GPIO19 19

static struct gpiod_chip *chip;
static struct gpiod_line *line18, *line19;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct timespec sleep_time = {0, 500000000}; // 0.5 seconds
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO18, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line19 = gpiod_chip_get_line(chip, GPIO19);
    if (!line19) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO19, strerror(errno));
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line18, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO18, strerror(errno));
        gpiod_line_release(line18);
        gpiod_line_release(line19);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line19, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO19, strerror(errno));
        gpiod_line_release(line18);
        gpiod_line_release(line19);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        // Set GPIO18 to HIGH
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d to HIGH: %s\n", GPIO18, strerror(errno));
        } else {
            printf("GPIO18 set to HIGH\n");
        }

        // Set GPIO19 to LOW
        ret = gpiod_line_set_value(line19, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d to LOW: %s\n", GPIO19, strerror(errno));
        } else {
            printf("GPIO19 set to LOW\n");
        }

        // Sleep for 0.5 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                printf("Sleep interrupted by signal\n");
            } else {
                fprintf(stderr, "Error during sleep: %s\n", strerror(errno));
            }
        }
    }

    // Release GPIO lines
    gpiod_line_release(line18);
    gpiod_line_release(line19);
    gpiod_chip_close(chip);

    printf("GPIO control stopped.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int setup_uart(const char *device, speed_t baud_rate) {
    int uart_fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 5;                             // 0.5 seconds read timeout

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return -1;
    }

    return uart_fd;
}

int read_uart(int uart_fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(uart_fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // No data available
        }
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    printf("UART communication started. Press Ctrl+C to exit.\n");

    while (program_running) {
        bytes_read = read_uart(uart_fd, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Retrying...\n");
            sleep(1); // Wait before retrying
        }
        usleep(10000); // Small delay to avoid busy-waiting
    }

    close(uart_fd);
    printf("UART communication stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_PIN_1 18
#define GPIO_PIN_2 23
#define GPIO_PIN_3 24

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(void);
int set_gpio_output(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int read_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize the GPIO chip
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    return 0;
}

// Function to set a GPIO pin as output
int set_gpio_output(int gpio_pin) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_request_output(line, "my_app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO pin
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read the value of a GPIO pin
int read_gpio_value(int gpio_pin) {
    struct gpiod_line *line = NULL;
    int ret;
    int value;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("Error getting GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    value = ret;
    gpiod_line_release(line);
    return value;
}

// Function to cleanup the GPIO chip
void cleanup_gpio(void) {
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    int state1 = 1, state2 = 0, state3 = 0;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set GPIO pins as output
    if (set_gpio_output(GPIO_PIN_1) != 0 ||
        set_gpio_output(GPIO_PIN_2) != 0 ||
        set_gpio_output(GPIO_PIN_3) != 0) {
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO values
        ret = set_gpio_value(GPIO_PIN_1, state1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value. Continuing.\n", GPIO_PIN_1);
        }
        ret = set_gpio_value(GPIO_PIN_2, state2);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value. Continuing.\n", GPIO_PIN_2);
        }
        ret = set_gpio_value(GPIO_PIN_3, state3);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value. Continuing.\n", GPIO_PIN_3);
        }

        // Print the state of each GPIO pin
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, state1, GPIO_PIN_2, state2, GPIO_PIN_3, state3);

        // Delay for 1 second
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int pwm_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as PWM output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_GPIO, 255);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO %d, frequency %d Hz. Press Ctrl+C to exit.\n", PWM_GPIO, PWM_FREQUENCY);

    while (!terminate) {
        // Generate PWM signal
        pwm_value = 128; // Example value, can be any integer from 0 to 255
        gpioPWM(PWM_GPIO, pwm_value);

        // Print the PWM value
        printf("PWM Value: %d\n", pwm_value);

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 27

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    config.consumer = "my_gpio_app";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) initialized as output\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Wait for 2 seconds
        sleep(2);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Wait for 2 seconds
        sleep(2);
    }

    // Release GPIO line
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d (BCM) released\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 10
#define PWM_PIN_4 11
#define PWM_PIN_5 17

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping PWM and exiting...\n", signal);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    int pwm_value = (int)((duty_cycle / PWM_RANGE) * 1000.0);
    gpioPWM(gpio, pwm_value);
    printf("GPIO %d: Duty cycle set to %d (PWM value: %d)\n", gpio, duty_cycle, pwm_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_5, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Example: Set duty cycles for each PWM pin
        set_pwm_duty_cycle(PWM_PIN_1, 500);
        set_pwm_duty_cycle(PWM_PIN_2, 750);
        set_pwm_duty_cycle(PWM_PIN_3, 250);
        set_pwm_duty_cycle(PWM_PIN_4, 750);
        set_pwm_duty_cycle(PWM_PIN_5, 750);

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM and terminate pigpio
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_5, 0);

    gpioTerminate();

    return 0;
}

