#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define DHT22_GPIO 4
#define MAX_TIMINGS 85

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int read_dht22_data(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    // Send start signal
    gpiod_line_set_value(line, 0);
    usleep(1000); // 1ms
    gpiod_line_set_value(line, 1);
    usleep(30); // 30us

    // Read response
    usleep(40);
    if (gpiod_line_get_value(line) != 0) {
        fprintf(stderr, "DHT22: No response (low)\n");
        return -1;
    }
    usleep(80);
    if (gpiod_line_get_value(line) != 1) {
        fprintf(stderr, "DHT22: No response (high)\n");
        return -1;
    }
    usleep(80);

    // Read data
    for (i = 0; i < MAX_TIMINGS; i++) {
        // Wait for low
        while (gpiod_line_get_value(line) == 1) {
            usleep(1); // Wait 1us
            if (errno) {
                fprintf(stderr, "DHT22: Timeout waiting for low\n");
                return -1;
            }
        }

        // Measure high duration
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0) {
            usleep(1); // Wait 1us
            if (errno) {
                fprintf(stderr, "DHT22: Timeout waiting for high\n");
                return -1;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Determine bit value
        if (duration > 40) {
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }

        bit_count++;
        if (bit_count == 40) break; // Expecting 40 bits of data
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22: Checksum error\n");
        return -1;
    }

    // Convert data
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100ms

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, DHT22_GPIO);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "dht22", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("DHT22 reader started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;

        if (read_dht22_data(DHT22_GPIO, &temperature, &humidity) == 0) {
            printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

