    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO17, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_line_release(line24);
        gpiod_line_release(line25);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line23, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO23, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_line_release(line24);
        gpiod_line_release(line25);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
