        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_line_release(line24);
        gpiod_line_release(line25);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO states
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO17, strerror(errno));
