#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <mosquitto.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "agriculture/sensor_data"
#define NUM_SENSORS 3

// Global variables
int spi_fd = -1;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void publish_sensor_data(int sensor_values[]);
void signal_handler(int signum);
int spi_init(void);
void spi_close(void);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize SPI interface
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Close SPI interface
void spi_close(void) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Publish sensor data to MQTT broker
void publish_sensor_data(int sensor_values[]) {
    char payload[256];
    int i;
    int ret;

    snprintf(payload, sizeof(payload), "{\"sensor_values\": [%d, %d, %d]}",
             sensor_values[0], sensor_values[1], sensor_values[2]);

    ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
    }
}

int main(int argc, char *argv[]) {
    int sensor_values[NUM_SENSORS];
    int i;

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        for (i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                sensor_values[i] = 0; // Set to 0 to avoid further issues
            }
        }

        // Publish sensor data
        publish_sensor_data(sensor_values);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    spi_close();
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <string.h>

#define DEVICE_NAME "/dev/video0" // Default camera device

int main() {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int n_buffers = 1;
    unsigned int buffer_size = 640 * 480 * 3; // 640x480 RGB24
    struct v4l2_buffer buf;
    unsigned char *buffer = NULL;
    FILE *fp = NULL;
    int i;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return 1;
    }

    // Check capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = n_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return 1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (fd < 0) {
        perror("VIDIOC_QUERYBUF");
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, req.count * buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    // Capture a single frame
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd = ioctl(fd, VIDIOC_QBUF, &buf);
    if (fd < 0) {
        perror("VIDIOC_QBUF");
        close(fd);
        munmap(buffer, req.count * buffer_size);
        return 1;
    }

    fd = ioctl(fd, VIDIOC_STREAMON, &buf.type);
    if (fd < 0) {
        perror("VIDIOC_STREAMON");
        close(fd);
        munmap(buffer, req.count * buffer_size);
        return 1;
    }

    fd = ioctl(fd, VIDIOC_DQBUF, &buf.type);
    if (fd < 0) {
        perror("VIDIOC_DQBUF");
        close(fd);
        munmap(buffer, req.count * buffer_size);
        return 1;
    }

    // Save the image to a file
    fp = fopen("image.rgb", "wb");
    if (fp == NULL) {
        perror("fopen");
        close(fd);
        munmap(buffer, req.count * buffer_size);
        return 1;
    }

    fwrite(buffer, 1, req.count * buffer_size, fp);
    fclose(fp);

    // Stop streaming
    fd = ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
    if (fd < 0) {
        perror("VIDIOC_STREAMOFF");
        close(fd);
        munmap(buffer, req.count * buffer_size);
        return 1;
    }

    // Unmap the buffer
    munmap(buffer, req.count * buffer_size);

    // Close the device
    close(fd);

    printf("Image saved to image.rgb\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 4
#define PWM_PIN_2 5
#define PWM_PIN_3 6
#define PWM_PIN_4 7
#define PWM_PIN_5 8
#define PWM_PIN_6 9

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nSIGINT received, stopping PWM outputs...\n");
    }
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    int pwm_value = (int)((duty_cycle / PWM_RANGE) * 1000.0);
    gpioPWM(gpio_pin, pwm_value);
    printf("GPIO %d: Duty cycle = %d, PWM value = %d\n", gpio_pin, duty_cycle, pwm_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Set PWM frequency for each pin
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_6, PWM_FREQUENCY);

    // Set PWM range for each pin
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_5, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_6, PWM_RANGE);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Example: Set duty cycles for each pin
        set_pwm_duty_cycle(PWM_PIN_1, 500);
        set_pwm_duty_cycle(PWM_PIN_2, 750);
        set_pwm_duty_cycle(PWM_PIN_3, 250);
        set_pwm_duty_cycle(PWM_PIN_4, 750);
        set_pwm_duty_cycle(PWM_PIN_5, 750);
        set_pwm_duty_cycle(PWM_PIN_6, 750);

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM outputs and terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_CHIP 0
#define GPIO_PIN 17
#define GPIO_PIN_2 18

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio_line;
struct gpiod_line *gpio_line_2;

// Function prototypes
int initialize_gpio(void);
int set_gpio_value(int gpio, int value);
int cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCtrl+C pressed. Cleaning up and exiting.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Initializes the GPIO chip and lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!gpio_line_2) {
        perror("Error getting GPIO line 2");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "my_gpio", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line_2, "my_gpio_2", 0) < 0) {
        perror("Error requesting GPIO line 2 as output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO pin
int set_gpio_value(int gpio, int value) {
    int ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Releases the GPIO lines and chip
int cleanup_gpio(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop for 3 cycles
    for (int i = 0; i < 3; i++) {
        // Set GPIO 17 to HIGH
        if (set_gpio_value(GPIO_PIN, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to HIGH. Exiting.\n", GPIO_PIN);
            cleanup_gpio();
            return 1;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        // Set GPIO 18 to LOW
        if (set_gpio_value(GPIO_PIN_2, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to LOW. Exiting.\n", GPIO_PIN_2);
            cleanup_gpio();
            return 1;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN_2);

        // Wait for 1 second
        sleep(1);

        // Set GPIO 17 to LOW
        if (set_gpio_value(GPIO_PIN, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to LOW. Exiting.\n", GPIO_PIN);
            cleanup_gpio();
            return 1;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        // Set GPIO 18 to HIGH
        if (set_gpio_value(GPIO_PIN_2, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to HIGH. Exiting.\n", GPIO_PIN_2);
            cleanup_gpio();
            return 1;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN_2);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Set GPIO high
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d high: %s\n", GPIO_PIN, strerror(errno));
        } else {
            printf("GPIO %d set HIGH\n", GPIO_PIN);
