void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct timespec start, end;
    long long elapsed_ns;
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as input
    memset(&config, 0, sizeof(config));
    config.consumer = "HC-SR04";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Measure echo pulse
        if (gpiod_line_request(line, &config, 0) < 0) {
            perror("Error re-requesting GPIO line");
            break; // Exit loop if re-request fails
        }

        // Trigger a measurement
        gpiod_line_set_value(line, 1);
        nanosleep(&(struct timespec){0, 10000000}, NULL); // 10us trigger pulse
        gpiod_line_set_value(line, 0);

        // Wait for echo to start (with timeout)
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            if ((start.tv_sec - start.tv_nsec / 1000000000) > 100000) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                break;
            }
        }

        // Measure echo pulse width
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
            if (elapsed_ns > 1000000000) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                break;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate distance in centimeters
        double distance = (double)(elapsed_ns / 1000000000.0) / 2.0;

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Release the GPIO line
        if (gpiod_line_release(line) < 0) {
            perror("Error releasing GPIO line");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

