#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN 18
#define ENABLE_PIN 8
#define CS_PIN 9
#define SCK_PIN 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Global variable for SPI handle
int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
void set_pwm_duty_cycle(int duty_cycle);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(PWM_PIN, duty_cycle);
    printf("PWM duty cycle set to %d\n", duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Enable PWM
    gpioPWM(PWM_PIN, 128); // 50% duty cycle initially

    // Open SPI channel
    spi_config_t spi_config = {SPI_CHANNEL, SPI_SPEED};
    spi_handle = spiOpen(spi_config.channel, spi_config.speed, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        // Map ADC value to PWM duty cycle (0-255)
        int duty_cycle = (int)(((float)adc_value / 1023.0) * 255.0);

        // Set PWM duty cycle
        set_pwm_duty_cycle(duty_cycle);

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    return 0;
}

