#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3)
#define CAPTURE_INTERVAL_SEC 0.1

static int fd = -1; // File descriptor for the video device
static void *buffer = NULL; // Pointer to the buffer memory
static unsigned int buffer_size = 0; // Size of the buffer in bytes
static volatile sig_atomic_t keep_running = 1; // Flag to control the main loop

// Structure to hold image data
typedef struct {
    unsigned char *data;
    int width;
    int height;
} Image;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting...\n");
        keep_running = 0;
    }
}

// Function to initialize the video device
int init_v4l2() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    buffer_size = req.length;
    buffer = mmap(NULL, req.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    for (i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            munmap(buffer, buffer_size);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        munmap(buffer, buffer_size);
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image(Image *image) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    image->width = IMAGE_WIDTH;
    image->height = IMAGE_HEIGHT;
    image->data = (unsigned char *)buffer;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to save the image to a file
int save_image(const Image *image, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(image->data, 1, IMAGE_SIZE, fp);
    if (bytes_written != IMAGE_SIZE) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, IMAGE_SIZE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        if (munmap(buffer, buffer_size) == -1) {
            perror("Error unmapping buffer");
        }
        close(fd);
    }
}

int main() {
    struct timespec req, rem;
    req.tv_sec = CAPTURE_INTERVAL_SEC;
    req.tv_nsec = 0;

    signal(SIGINT, signal_handler);

    if (init_v4l2() < 0) {
        fprintf(stderr, "Failed to initialize V4L2. Exiting.\n");
        return EXIT_FAILURE;
    }

    Image image;
    image.width = IMAGE_WIDTH;
    image.height = IMAGE_HEIGHT;
    image.data = NULL; // Initialize to NULL

    printf("Capturing images every %f seconds. Press Ctrl+C to exit.\n", CAPTURE_INTERVAL_SEC);

    while (keep_running) {
        if (capture_image(&image) == 0) {
            if (save_image(&image, "image.rgb") == 0) {
                printf("Captured image saved to image.rgb\n");
            } else {
                fprintf(stderr, "Failed to save image\n");
            }
        } else {
            fprintf(stderr, "Failed to capture image\n");
        }
        nanosleep(&req, &rem);
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

