// Define the I2C address of the PCF8574
#define PCF8574_ADDR 0x27

// Define the I2C device file
#define I2C_DEV "/dev/i2c-1"

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Function to write a byte to the PCF8574
int write_pcf8574(int fd, int value) {
    unsigned char data[2];
    data[0] = 0x00; // Control byte: Write to the PCF8574
    data[1] = value; // The value to write

    if (write(fd, data, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from the PCF8574
int read_pcf8574(int fd) {
    unsigned char data[2];
    data[0] = 0x01; // Control byte: Read from the PCF8574
    if (write(fd, data, 1) != 1) {
        perror("Failed to write to I2C device (for read)");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return data[0];
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the PCF8574
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Main loop to display values on the PCF8574
    while (1) {
        // Read the value from the PCF8574
        int value = read_pcf8574(i2c_fd);
        if (value < 0) {
            fprintf(stderr, "Error reading from PCF8574, exiting.\n");
            break;
        }

        // Write the value back to the PCF8574
        if (write_pcf8574(i2c_fd, value) < 0) {
            fprintf(stderr, "Error writing to PCF8574, exiting.\n");
            break;
        }

        // Delay for 1 second
        sleep(1);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

