    int ret;
    struct timespec start, end;
    long long duration;

    ret = gpiod_line_get_value(echo_line);
    if (ret < 0) {
        perror("Error getting echo line value");
        return -1;
    }

    // Wait for echo to go high
    do {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            perror("Error getting echo line value");
            return -1;
        }
    } while (ret == 0 && program_running);

    if (!program_running) return -1; // Exit if signal received

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo to go low
    do {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
