            return -1;
        }
    } while (ret == 1 && program_running);

    if (!program_running) return -1; // Exit if signal received

    clock_gettime(CLOCK_MONOTONIC, &end);

    duration = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

