int read_accelerometer_data(int fd, int *x, int *y, int *z) {
    int x_high, x_low, y_high, y_low, z_high, z_low;

    x_high = read_mpu6050(fd, ACCEL_XOUT_H);
    x_low = read_mpu6050(fd, ACCEL_XOUT_H + 1);
    y_high = read_mpu6050(fd, ACCEL_XOUT_H + 2);
    y_low = read_mpu6050(fd, ACCEL_XOUT_H + 3);
    z_high = read_mpu6050(fd, ACCEL_XOUT_H + 4);
