#define GPIO_NUM 0 // GPIO 17
#define GPIO_NUM 1 // GPIO 18
#define GPIO_NUM 2 // GPIO 27

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *gpio17_line, *gpio18_line, *gpio27_line;

// Function prototypes
int initialize_gpio(void);
int set_gpio_output(struct gpiod_line *line, int value);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCtrl+C pressed. Cleaning up and exiting.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio17_line = gpiod_chip_get_line(chip, GPIO_NUM);
    if (!gpio17_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpio18_line = gpiod_chip_get_line(chip, GPIO_NUM);
    if (!gpio18_line) {
        perror("Error getting GPIO line");
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpio27_line = gpiod_chip_get_line(chip, GPIO_NUM);
    if (!gpio27_line) {
        perror("Error getting GPIO line");
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio17_line, "output", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(gpio27_line);
        gpiod_line_release(gpio18_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio18_line, "output", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(gpio27_line);
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio27_line, "output", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(gpio27_line);
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO output value
int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio18_line) {
        gpiod_line_release(gpio18_line);
    }
    if (gpio27_line) {
        gpiod_line_release(gpio27_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("GPIO initialized successfully.\n");

    // Main loop
    while (1) {
        // Set GPIO 17 to HIGH
        if (set_gpio_output(gpio17_line, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 17 to HIGH.\n");
        } else {
            printf("GPIO 17 set to HIGH\n");
        }

        // Set GPIO 18 to LOW
        if (set_gpio_output(gpio18_line, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO 18 to LOW.\n");
        } else {
            printf("GPIO 18 set to LOW\n");
        }

        // Set GPIO 27 to HIGH
        if (set_gpio_output(gpio27_line, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 27 to HIGH.\n");
        } else {
            printf("GPIO 27 set to HIGH\n");
        }

        // Delay for 1 second
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature and humidity from SHT31
int read_sht31(int fd, float *temperature, float *humidity) {
    unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    unsigned char data[6];
    int ret;

    ret = write(fd, cmd, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    usleep(20000); // Wait for measurement (20ms)

    ret = read(fd, data, 6);
    if (ret != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to temperature and humidity
    int temp_raw = (data[0] << 8) | data[1];
    int hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

int main() {
    float temperature, humidity;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("SHT31 sensor reading started. Press Ctrl+C to exit.\n");

    while (1) {
        if (read_sht31(i2c_fd, &temperature, &humidity) == 0) {
            // Validate temperature and humidity
            if (temperature >= -50.0 && temperature <= 100.0 && humidity >= 0.0 && humidity <= 100.0) {
                // Get current timestamp
                time(&now);
                timeinfo = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Print temperature and humidity with timestamp
                printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
            } else {
                fprintf(stderr, "Invalid temperature or humidity reading.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_PINS {5, 6, 12, 16, 19, 20, 23, 24, 25, 26}

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *lines[10]; // Array to hold GPIO lines
int num_lines = 0;
int running = 1;

// Function prototypes
int initialize_gpio(void);
int set_gpio_output(int gpio);
int apply_output_state(int state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initializes the GPIO chip and lines
int initialize_gpio(void) {
    int i;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", "gpiochip0");
        return -1;
    }

    num_lines = 0;
    for (i = 0; i < 10; i++) {
        lines[i] = NULL;
    }

    for (i = 0; i < 10; i++) {
        int gpio = GPIO_PINS[i];
        struct gpiod_line *line = gpiod_chip_get_line(chip, gpio);

        if (!line) {
            fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio);
            return -1;
        }

        if (num_lines == 0) {
            lines[num_lines++] = line;
        } else {
            fprintf(stderr, "Error: Too many GPIO lines. Expected %d, got %d\n", num_lines, i + 1);
            return -1;
        }

        ret = gpiod_line_request_output(line, "output", 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not request GPIO line %d as output\n", gpio);
            return -1;
        }
    }

    return 0;
}

// Sets the specified GPIO pin as an output
int set_gpio_output(int gpio) {
    int i;
    for (i = 0; i < 10; i++) {
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: GPIO line for GPIO %d not initialized\n", gpio);
            return -1;
        }
        if (lines[i]->line == gpio) {
            return 0; // Already initialized
        }
    }
    fprintf(stderr, "Error: GPIO %d not found in array\n", gpio);
    return -1;
}

// Applies the specified state to all GPIO pins
int apply_output_state(int state) {
    int i;
    for (i = 0; i < 10; i++) {
        if (lines[i] != NULL) {
            int ret = gpiod_line_set_value(lines[i], state);
            if (ret < 0) {
                fprintf(stderr, "Error: Could not set value for GPIO line %d\n", lines[i]->line);
                return -1;
            }
        }
    }
    return 0;
}

// Cleans up the GPIO chip and lines
void cleanup_gpio(void) {
    int i;
    if (chip) {
        for (i = 0; i < num_lines; i++) {
            if (lines[i] != NULL) {
                gpiod_line_release(lines[i]);
            }
        }
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int state = 0; // Initial state (LOW)

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Apply output state
        if (apply_output_state(state) != 0) {
            fprintf(stderr, "Error: Failed to apply output state\n");
        }

        // Toggle state
        state = !state;
        usleep(100000); // 100ms delay
    }

    // Clean up GPIO
    cleanup_gpio();

    printf("GPIO control program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_PIN_1 17
#define GPIO_PIN_2 22
#define GPIO_PIN_3 27

// Global variable to store the GPIO chip name
char *chip_name = "/sys/class/gpio/gpiochip0";

// Global variable to store the GPIO line numbers
int line_numbers[] = {GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3};
int num_lines = sizeof(line_numbers) / sizeof(line_numbers[0]);

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to initialize the GPIO chip
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", chip_name);
        return -1;
    }

    for (int i = 0; i < num_lines; i++) {
        int line = line_numbers[i];
        struct gpiod_line *line = gpiod_chip_get_line(chip, line);
        if (!line) {
            fprintf(stderr, "Error getting GPIO line %d\n", line);
            gpiod_chip_close(chip);
            return -1;
        }

        if (gpiod_line_request_output(line, "my_gpio", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output\n", line);
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

// Function to set the GPIO pin state
int set_gpio_state(int pin, int state) {
    int ret;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);

    ret = write(pin, state ? "1" : "0", 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to cleanup the GPIO chip
void cleanup_gpio() {
    for (int i = 0; i < num_lines; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, line_numbers[i]);
        if (line) {
            gpiod_line_release(line);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO chip
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        for (int i = 0; i < num_lines; i++) {
            if (set_gpio_state(line_numbers[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %d to HIGH\n", line_numbers[i]);
            }
            printf("GPIO %d set to HIGH\n", line_numbers[i]);
        }
        sleep(1);

        for (int i = 0; i < num_lines; i++) {
            if (set_gpio_state(line_numbers[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %d to LOW\n", line_numbers[i]);
            }
            printf("GPIO %d set to LOW\n", line_numbers[i]);
        }
        sleep(1);
    }

    // Cleanup GPIO before exiting (should not reach here due to signal handler)
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to set PWM frequency
int set_pwm_frequency(int gpio) {
    int result = gpioSetPWMfrequency(gpio, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to set PWM range
int set_pwm_range(int gpio) {
    int result = gpioSetPWMrange(gpio, PWM_RANGE);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    int result = gpioPWM(gpio, duty_cycle);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set PWM frequency for each GPIO pin
    if (set_pwm_frequency(PWM_PIN_1) != 0 ||
        set_pwm_frequency(PWM_PIN_2) != 0 ||
        set_pwm_frequency(PWM_PIN_3) != 0 ||
        set_pwm_frequency(PWM_PIN_4) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM range for each GPIO pin
    if (set_pwm_range(PWM_PIN_1) != 0 ||
        set_pwm_range(PWM_PIN_2) != 0 ||
        set_pwm_range(PWM_PIN_3) != 0 ||
        set_pwm_range(PWM_PIN_4) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set PWM duty cycle for each GPIO pin
        if (set_pwm_duty_cycle(PWM_PIN_1, 500) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_2, 500) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_3, 500) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_4, 500) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }

        // Print the state applied to each GPIO pin
        printf("GPIO %d: %d\n", PWM_PIN_1, gpioGetPWMdutycycle(PWM_PIN_1));
        printf("GPIO %d: %d\n", PWM_PIN_2, gpioGetPWMdutycycle(PWM_PIN_2));
        printf("GPIO %d: %d\n", PWM_PIN_3, gpioGetPWMdutycycle(PWM_PIN_3));
        printf("GPIO %d: %d\n", PWM_PIN_4, gpioGetPWMdutycycle(PWM_PIN_4));

        // Delay for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Stop PWM output and terminate pigpio library
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_PIN_ALT 3

static struct gpiod_chip *chip;
static struct gpiod_line *line_gpio;
static struct gpiod_line *line_gpio_alt;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line_gpio = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line_gpio) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO line for alternative use
    line_gpio_alt = gpiod_chip_get_line(chip, GPIO_PIN_ALT);
    if (!line_gpio_alt) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_ALT, strerror(errno));
        gpiod_line_release(line_gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line_gpio, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(line_gpio_alt);
        gpiod_line_release(line_gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line_gpio_alt, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN_ALT, strerror(errno));
        gpiod_line_release(line_gpio);
        gpiod_line_release(line_gpio_alt);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Set GPIO state
        if (gpiod_line_set_value(line_gpio, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN, strerror(errno));
        } else {
            printf("GPIO %d set HIGH\n", GPIO_PIN);
        }

        if (gpiod_line_set_value(line_gpio_alt, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_ALT, strerror(errno));
        } else {
            printf("GPIO %d (ALT) set HIGH\n", GPIO_PIN_ALT);
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line_gpio);
    gpiod_line_release(line_gpio_alt);
    gpiod_chip_close(chip);

    printf("GPIO control program finished.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_PIN_ALT 17
#define GPIO_LINE "out"
#define GPIO_PATH "/sys/class/gpio"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 60;
    sleep_time.tv_nsec = 0;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "my_app", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO high
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO high");
            break; // Exit loop on error
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Set GPIO low
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO low");
            break; // Exit loop on error
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Sleep for 60 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit gracefully
                break;
            }
            perror("nanosleep interrupted");
            break; // Exit loop on error
        }
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

