#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <string.h>

#define DEVICE_NAME "/dev/video0" // Default camera device

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int n_buffers;
    struct v4l2_buffer buf;
    unsigned int i;
    char filename[64];
    int ret;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Query device capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Set desired width
    fmt.fmt.pix.height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    n_buffers = req.count;

    // Allocate buffers
    for (i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
        if (ret < 0) {
            perror("Error querying buffer");
            close(fd);
            return 1;
        }

        buf.length = buf.length;
        buf.bytesused = buf.bytesused;
    }

    // Queue the buffer for streaming
    for (i = 0; i < n_buffers; i++) {
        ret = ioctl(fd, VIDIOC_QBUF, &buf[i]);
        if (ret < 0) {
            perror("Error queuing buffer");
            close(fd);
            return 1;
        }
    }

    // Start streaming
    ret = ioctl(fd, VIDIOC_STREAMON, &cap.cap.features);
    if (ret < 0) {
        perror("Error starting stream");
        close(fd);
        return 1;
    }

    // Capture a single frame
    ret = ioctl(fd, VIDIOC_DQBUF, &buf[0]);
    if (ret < 0) {
        perror("Error dequeueing buffer");
        close(fd);
        return 1;
    }

    // Save the image to a file
    snprintf(filename, sizeof(filename), "image_%04d.jpg", (i + 1));
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        close(fd);
        return 1;
    }

    fwrite(buf.data, buf.bytesused, 1, fp);
    fclose(fp);

    // Stop streaming
    ret = ioctl(fd, VIDIOC_STREAMOFF, &cap.cap.features);
    if (ret < 0) {
        perror("Error stopping stream");
        close(fd);
        return 1;
    }

    // Dequeue the buffer
    ret = ioctl(fd, VIDIOC_QBUF, &buf[0]);
    if (ret < 0) {
        perror("Error requeuing buffer");
        close(fd);
        return 1;
    }

    // Close the device
    close(fd);

    printf("Image saved to %s\n", filename);

    return 0;
}

