int set_gpio_value(int gpio_pin, int value);
int read_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize the GPIO chip
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    return 0;
}

// Function to set a GPIO pin as output
int set_gpio_output(int gpio_pin) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_request_output(line, "my_app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO pin
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read the value of a GPIO pin
int read_gpio_value(int gpio_pin) {
    struct gpiod_line *line = NULL;
    int ret;
    int value;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("Error getting GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    value = ret;
    gpiod_line_release(line);
    return value;
}

// Function to cleanup the GPIO chip
void cleanup_gpio(void) {
    if (chip) {
        gpiod_chip_close(chip);
    }
}

