    int i;
    int value;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO chip
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set GPIO pins as output
    for (i = GPIO_PIN_1; i <= GPIO_PIN_4; i++) {
        if (set_gpio_output(i) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output. Exiting.\n", i);
            cleanup_gpio();
            return 1;
        }
    }

    // Main loop
    while (1) {
        for (i = GPIO_PIN_1; i <= GPIO_PIN_4; i++) {
            // Read current value
