            if (set_gpio_value(i, value) != 0) {
                fprintf(stderr, "Failed to set GPIO %d value. Continuing.\n", i);
                continue; // Continue to the next GPIO
            }

            // Print the new value
            printf("GPIO %d: %d\n", i, value);
        }

        sleep(5);
    }

    return 0;
