        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", GPIO18);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

