    ret = gpiod_line_request_output(line17, "output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %d\n", GPIO17, ret);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 18 as output
    ret = gpiod_line_request_output(line18, "output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %d\n", GPIO18, ret);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO 17 HIGH
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d HIGH: %d\n", GPIO17, ret);
        } else {
            printf("GPIO %d set HIGH\n", GPIO17);
        }

        // Set GPIO 18 LOW
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d LOW: %d\n", GPIO18, ret);
        } else {
            printf("GPIO %d set LOW\n", GPIO18);
        }

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
