        long long echo_time = echo_time();

        if (echo_time > 0) {
            printf("State: ECHO, Time: %lld\n", echo_time);
        } else {
            printf("State: No ECHO\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

// Initialize GPIO lines
int init_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Open TRIGGER_PIN
    line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!line) {
        perror("Error getting TRIGGER_PIN line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "trigger", 0);
    if (ret < 0) {
        perror("Error requesting TRIGGER_PIN as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Open ECHO_PIN
    line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line) {
        perror("Error getting ECHO_PIN line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line, "echo", 0);
    if (ret < 0) {
        perror("Error requesting ECHO_PIN as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Link the lines in a circular list
    lines = (struct gpiod_line *)malloc(sizeof(struct gpiod_line));
    if (!lines) {
        perror("Error allocating memory for GPIO lines");
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }
    lines->next = lines;
    lines->next = lines;

    gpiod_line_set_drvdata(line, chip);
    gpiod_line_set_drvdata(line, chip);

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse(void) {
    struct timespec pulse_duration;
    pulse_duration.tv_sec = 0;
    pulse_duration.tv_nsec = 10000; // 10 microseconds

    int ret = gpiod_line_set_value(lines, 1); // Set trigger pin HIGH
    if (ret < 0) {
        perror("Error setting trigger pin HIGH");
        program_running = 0; // Stop the program
        return;
    }
    nanosleep(&pulse_duration, NULL);

    ret = gpiod_line_set_value(lines, 0); // Set trigger pin LOW
    if (ret < 0) {
        perror("Error setting trigger pin LOW");
        program_running = 0; // Stop the program
        return;
    }
}

// Measure the echo pulse duration
long long echo_time(void) {
    struct timespec start, end;
    long long start_ns, end_ns, diff_ns;

    // Wait for the echo pin to go HIGH
    do {
        ret = gpiod_line_get_value(lines);
        if (ret < 0) {
            perror("Error getting echo pin value");
            return 0; // Return 0 if error occurs
        }
        if (ret) {
            break;
        }
        nanosleep(&sleep_time, NULL);
    } while (1);

    if (!program_running) return 0; // Exit if program is stopping

    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for the echo pin to go LOW
    do {
        ret = gpiod_line_get_value(lines);
        if (ret < 0) {
            perror("Error getting echo pin value");
            return 0; // Return 0 if error occurs
        }
        if (!ret) {
            break;
        }
        nanosleep(&sleep_time, NULL);
    } while (1);

    if (!program_running) return 0; // Exit if program is stopping

    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    diff_ns = end_ns - start_ns;
    return diff_ns;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    struct gpiod_line *current = lines;
    struct gpiod_line *next;

    while (current) {
        next = current->next;
        gpiod_line_set_drvdata(current->next, NULL); // Detach the line from the chip
        gpiod_line_release(current->next);
        current = next;
    }

    gpiod_chip_close(GPIOCHIP);
    free(lines);
}

// Signal handler for SIGINT
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0; // Stop the main loop
    }
}

