void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read analog value from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // Construct the I2C message to send to the MCP3008
    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00; // Don't care

    // Transfer the data
    if (i2cWriteDevice(i2c_handle, (char *)spi_data, 3) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    // Read the response from the MCP3008
    unsigned char response[3];
    if (i2cReadDevice(i2c_handle, (char *)response, 3) != 0) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((response[1] & 0x03) << 8) + response[2];

    return adc_value;
}

