void set_pwm(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Invalid duty cycle %d\n", duty_cycle);
        return;
    }

    gpioPWM(PWM_PIN, duty_cycle);
    printf("PWM set to %d\n", duty_cycle);
}

