int send_dht22_request(int gpio) {
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "dht22";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(gpiod_line_get_line(chip, gpio), &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output for DHT22 request");
        return -1;
    }

    usleep(10000); // 10ms
    ret = gpiod_line_release(gpiod_line_get_line(chip, gpio), 0);
    if (ret < 0) {
        perror("Error releasing GPIO line after DHT22 request");
        return -1;
    }

    return 0;
}

// Function to read data from the DHT22 sensor
int read_dht22_data(int gpio, float *temperature, float *humidity) {
    int ret;
    unsigned int data[5] = {0, 0, 0, 0, 0};
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "dht22";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(gpiod_line_get_line(chip, gpio), &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as input for DHT22 read");
        return -1;
    }

    usleep(10000); // 10ms

    // Read 40 bits of data
    for (int i = 0; i < 40; i++) {
        unsigned int bit = 0;
        for (int j = 0; j < 8; j++) {
            // Wait for the line to go high
            while (gpiod_line_get_value(gpiod_line_get_line(chip, gpio)) == 0) {
                usleep(1); // Small delay to avoid busy-waiting
            }

            // Measure the duration of the high pulse
            struct timespec start, end;
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(gpiod_line_get_line(chip, gpio)) == 1) {
                usleep(1); // Small delay to avoid busy-waiting
            }
            clock_gettime(CLOCK_MONOTONIC, &end);

            // Calculate the duration in nanoseconds
            unsigned long long duration = (end.tv_sec - start.tv_sec) * 1000000000ULL + (end.tv_nsec - start.tv_nsec);

            // Determine if the pulse is long or short
            if (duration > 40) {
                bit = 1;
            } else {
                bit = 0;
            }
        }

        data[i / 8] |= (bit << (7 - (i % 8)));
    }

    ret = gpiod_line_release(gpiod_line_get_line(chip, gpio), 0);
    if (ret < 0) {
        perror("Error releasing GPIO line after DHT22 read");
        return -1;
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error: Data[0:3] = 0x%X, Data[4] = 0x%X\n", (data[0] + data[1] + data[2] + data[3]), data[4]);
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) | data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) | data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0;
}

