#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// MAX31855 register addresses
#define MAX31855_CONFIG_REG 0x00
#define MAX31855_FAULT_REG 0x01
#define MAX31855_TEMP_MSB_REG 0x02
#define MAX31855_TEMP_LSB_REG 0x03
#define MAX31855_VBIAS_MSB_REG 0x04
#define MAX31855_VBIAS_LSB_REG 0x05

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to read a register from the MAX31855
uint8_t read_register(uint8_t reg_addr) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    struct spi_ioc_transfer transfer[1];

    // Set the transmit buffer (address + 1 for read)
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte

    // Set the receive buffer
    rx_buf[0] = 0x00; // Dummy byte
    rx_buf[1] = 0x00;

    // Configure the SPI transfer
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 2;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Perform the SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        return 0; // Return 0 on error
    }

    // Extract the received data
    return rx_buf[1];
}

// Function to write a register to the MAX31855
void write_register(uint8_t reg_addr, uint8_t data) {
    uint8_t tx_buf[2];
    struct spi_ioc_transfer transfer[1];

    // Set the transmit buffer (data + 1 for write)
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    // Configure the SPI transfer
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)0x00; // Dummy receive buffer
    transfer[0].len = 2;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Perform the SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        return; // Return on error
    }
}

// Function to read the temperature from the MAX31855
int32_t read_temperature() {
    uint8_t msb, lsb, config;

    // Read the configuration register
    config = read_register(MAX31855_CONFIG_REG);
    if (config != 0x00) {
        fprintf(stderr, "Error: Invalid configuration register value: 0x%02X\n", config);
        return -1; // Indicate error
    }

    // Read the temperature data
    msb = read_register(MAX31855_TEMP_MSB_REG);
    lsb = read_register(MAX31855_TEMP_LSB_REG);

    // Combine the MSB and LSB to form the 14-bit temperature value
    int32_t raw_temp = ((int32_t)msb << 8) | (int32_t)lsb;

    // Check for fault conditions
    uint8_t fault = read_register(MAX31855_FAULT_REG);
    if (fault & 0x01) {
        fprintf(stderr, "Error: MAX31855 Fault detected (Open Circuit)\n");
        return -1; // Indicate error
    }
    if (fault & 0x02) {
        fprintf(stderr, "Error: MAX31855 Fault detected (Short to VCC)\n");
        return -1; // Indicate error
    }
    if (fault & 0x04) {
        fprintf(stderr, "Error: MAX31855 Fault detected (Short to GND)\n");
        return -1; // Indicate error
    }

    // Check for negative temperature
    if (raw_temp & 0x8000) {
        raw_temp |= 0xFFFFC000; // Sign extend to 32 bits
    }

    // Convert the raw temperature to Celsius (resolution is 0.25 degrees C)
    return raw_temp >> 2;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Configure SPI bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int32_t temperature = read_temperature();
        if (temperature >= 0) {
            printf("Temperature: %d\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(1);
    }

    // The following lines will never be reached because of the infinite loop.
    close(spi_fd);
    return 0;
}

