    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
    struct gpiod_line_request_config config;

    // Request trigger line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "trigger_consumer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;
    if (gpiod_line_request(trigger_line, &config, 0) < 0) {
        perror("Error requesting trigger line as output");
        return -1;
    }

    // Request echo line as input
    memset(&config, 0, sizeof(config));
    config.consumer = "echo_consumer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;
    if (gpiod_line_request(echo_line, &config, 0) < 0) {
        perror("Error requesting echo line as input");
        return -1;
    }

    // Request echo2 line as input
    memset(&config, 0, sizeof(config));
