    config.consumer = "echo3_consumer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;
    if (gpiod_line_request(echo3_line, &config, 0) < 0) {
        perror("Error requesting echo3 line as input");
        return -1;
    }

    return 0;
}

// Generate a trigger pulse
void trigger_pulse(void) {
    struct gpiod_line_request_config config;

    // Request trigger line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "trigger_consumer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;
    if (gpiod_line_request(trigger_line, &config, 0) < 0) {
        perror("Error requesting trigger line as output for pulse");
        return;
    }

    // Set trigger line high
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        return;
    }

    // Wait for 10 microseconds
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10000; // 10 microseconds
    nanosleep(&ts, NULL);

    // Set trigger line low
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return;
    }

    // Release the line
    if (gpiod_line_release(trigger_line) < 0) {
        perror("Error releasing trigger line");
    }
}

// Callback function for echo pin
void echo_callback(struct gpiod_line *line, int edge, unsigned int value, unsigned int *last_value) {
    if (edge == GPIOD_LINE_EDGE_RISING) {
