            }
            clock_gettime(CLOCK_MONOTONIC, &end);

            // Calculate pulse duration in microseconds
            double pulse_duration = (end.tv_sec - start.tv_sec) * 1000000.0 + (end.tv_nsec - start.tv_nsec) / 1000.0;

            // Calculate distance
            double distance = pulse_duration / 29.1; // Speed of sound in air is approximately 343 m/s or 0.0343 cm/us

            printf("Distance: %.2f cm\n", distance);

            // Check if distance exceeds threshold
            if (distance > DISTANCE_THRESHOLD) {
                printf("Distance exceeds threshold!\n");
            }
        }
    }
}

