    double end_time = end.tv_sec + end.tv_nsec / 1000000000.0;

    double pulse_duration = (end_time - start_time) * 1000000.0;

    // Calculate distance
    double distance = pulse_duration / 29.1; // Speed of sound in air is approximately 343 m/s or 0.0343 cm/us

    return distance;
}

