#include <errno.h>

// Define the GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIOLINE 18

// Global variable to store the GPIO line
struct gpiod_line *gpio_line = NULL;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    exit(0);
}

// Function to initialize the GPIO line
int initialize_gpio(struct gpiod_line **gpio_line) {
    int ret;

    // Open the GPIO chip
    ret = gpiod_chip_open_by_name("gpiochip0", &gpio_chip);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(-ret));
        return -1;
    }

    // Get the GPIO line
    ret = gpiod_chip_get_line(gpio_chip, GPIOLINE, &gpio_line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIOLINE, strerror(-ret));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(*gpio_line, "my_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIOLINE, strerror(-ret));
        gpiod_line_release(*gpio_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to set the GPIO line state
int set_gpio_state(struct gpiod_line *gpio_line, int state) {
    int ret;

    ret = gpiod_line_set_value(gpio_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value to %d: %s\n", GPIOLINE, state, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to read the GPIO line state
int read_gpio_state(struct gpiod_line *gpio_line) {
    int ret;

    ret = gpiod_line_get_value(gpio_line);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO line %d value: %s\n", GPIOLINE, strerror(-ret));
        return -1;
    }

    return ret;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO line
    if (initialize_gpio(&gpio_line) < 0) {
        return 1;
    }

    printf("GPIO %d initialized successfully.\n", GPIOLINE);

    // Main loop
    while (1) {
        // Read the current state
        int current_state = read_gpio_state(gpio_line);
        if (current_state < 0) {
            fprintf(stderr, "Error reading current state. Exiting.\n");
            break;
        }

        // Set the new state
        if (set_gpio_state(gpio_line, 1) < 0) {
            fprintf(stderr, "Error setting new state. Exiting.\n");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIOLINE);

        // Wait for 1 second
        sleep(1);

        // Set the new state
        if (set_gpio_state(gpio_line, 0) < 0) {
            fprintf(stderr, "Error setting new state. Exiting.\n");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIOLINE);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

