int bme280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t data[8];

    if (i2c_read_bytes(fd, BME280_REG_PRESS_MSB, data, 8) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    *humidity = (data[6] << 8) | data[7];

    return 0;
}

// BME280 compensate temperature function
double bme280_compensate_temperature(int32_t raw_temp, struct bme280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temp / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// BME280 compensate pressure function
double bme280_compensate_pressure(int32_t raw_pressure, struct bme280_calib_data calib, double t_fine) {
    double var1, var2, p;
    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// BME280 compensate humidity function
double bme280_compensate_humidity(int32_t raw_humidity, struct bme280_calib_data calib, double t_fine) {
    double var_H;
    var_H = (((double)t_fine) - 76800.0);
    var_H = (raw_humidity - (((double)calib.dig_H4) * 64.0 + ((double)calib.dig_H5) / 16384.0 * var_H)) * (((double)calib.dig_H2) / 65536.0 * (1.0 + ((double)calib.dig_H6) / 67108864.0 * var_H * (1.0 + ((double)calib.dig_H3) / 67108864.0 * var_H)));
    var_H = var_H * (1.0 - ((double)calib.dig_H1) * var_H / 524288.0);
    if (var_H > 100.0)
        var_H = 100.0;
    else if (var_H < 0.0)
        var_H = 0.0;
    return var_H;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    int32_t raw_temperature, raw_pressure, raw_humidity;
    double temperature, pressure, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read calibration data
    if (bme280_read_calibration_data(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set sensor to forced mode
    if (i2c_write_byte(i2c_fd, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Failed to write humidity control register\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write_byte(i2c_fd, BME280_REG_CTRL_MEAS, 0x25) != 0) {
        fprintf(stderr, "Failed to write control measurement register\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Read raw data
        if (bme280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure, &raw_humidity) != 0) {
            fprintf(stderr, "Failed to read raw data\n");
            break;
        }

        // Compensate data
        temperature = bme280_compensate_temperature(raw_temperature, calib);
        pressure = bme280_compensate_pressure(raw_pressure, calib, temperature);
        humidity = bme280_compensate_humidity(raw_humidity, calib, temperature);

        // Get current timestamp
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print data
        printf("%s, Temperature: %.2f °C, Pressure: %.2f Pa, Humidity: %.2f %%\n", timestamp, temperature, pressure, humidity);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Set GPIO high
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d high: %s\n", GPIO_PIN, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);

        // Set GPIO low
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d low: %s\n", GPIO_PIN, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up GPIO...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06
#define VEML7700_ALS_INT 0x08
#define VEML7700_ALS_INT_EN 0x09
#define VEML7700_ALS_DATA 0x04

int i2c_fd;

void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    close(i2c_fd);
    exit(0);
}

int main() {
    int retries = 3;
    int result;
    unsigned char buf[2];
    unsigned int als_data;

    signal(SIGINT, cleanup);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure the sensor (example: gain 1, integration time 100ms)
    buf[0] = VEML7700_ALS_CONF;
    buf[1] = 0x01; // Gain 1, Integration Time 100ms
    while (retries > 0) {
        result = write(i2c_fd, buf, 2);
        if (result == 2) break;
        perror("Failed to write configuration");
        retries--;
        sleep(1); // Wait before retrying
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to configure sensor after multiple retries.\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read ALS data
        buf[0] = VEML7700_ALS_DATA;
        retries = 3;
        while (retries > 0) {
            result = write(i2c_fd, buf, 1);
            if (result == 1) break;
            perror("Failed to write register address");
            retries--;
            sleep(1);
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to write register address for ALS data.\n");
            continue; // Skip to the next iteration
        }

        retries = 3;
        while (retries > 0) {
            result = read(i2c_fd, buf, 2);
            if (result == 2) break;
            perror("Failed to read ALS data");
            retries--;
            sleep(1);
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        als_data = (buf[1] << 8) | buf[0];
        printf("ALS Value: %u\n", als_data);

        sleep(0.5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting...\n", signum);
}

int setup_uart(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = TIMEOUT_MS / 100;              // Timeout of 100ms

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart(int fd, char *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // No data available
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int uart_fd = setup_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return EXIT_FAILURE;
    }

    char buffer[256];
    time_t last_read_time = time(NULL);

    while (program_running) {
        int bytes_read = read_uart(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Retrying...\n");
        } else {
            // Device not responding, but we don't want to block indefinitely
            //printf("Device not responding. Retrying...\n");
        }

        time_t current_time = time(NULL);
        if (difftime(current_time, last_read_time) >= 1.0) {
            last_read_time = current_time;
            bytes_read = read_uart(uart_fd, buffer, sizeof(buffer) - 1);
            if (bytes_read > 0) {
                buffer[bytes_read] = '\0';
                printf("Received: %s\n", buffer);
            } else if (bytes_read < 0) {
                fprintf(stderr, "Error reading from UART. Retrying...\n");
            } else {
                //printf("Device not responding. Retrying...\n");
            }
        }
        usleep(100000); // 100ms
    }

    close(uart_fd);
    printf("UART port closed.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define sound speed in cm/us
#define SOUND_SPEED 0.0343

// Define timeout in seconds
#define TIMEOUT 0.1

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio(void);
int trigger_pulse(void);
long read_pulse_width(void);
float calculate_distance(long pulse_width);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCtrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        perror("Error requesting trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(echo_line, "echo", 0);
    if (ret < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Generate a 10us trigger pulse
int trigger_pulse(void) {
    int ret;
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10;

    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        perror("Error setting trigger line value");
        return -1;
    }
    nanosleep(&ts, NULL);
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        perror("Error setting trigger line value");
        return -1;
    }
    return 0;
}

// Read the echo pulse width
long read_pulse_width(void) {
    struct timespec start, end;
    long pulse_width = 0;
    int ret;

    ret = gpiod_line_get_value(echo_line);
    if (ret < 0) {
        perror("Error getting echo line value");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec) > TIMEOUT * 1000000000LL) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec) > TIMEOUT * 1000000000LL) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    return pulse_width;
}

// Calculate distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SOUND_SPEED / 2.0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int ret;
    long pulse_width;
    float distance;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 distance sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger pulse
        if (trigger_pulse() < 0) {
            fprintf(stderr, "Failed to trigger pulse. Continuing...\n");
            sleep(0.5);
            continue;
        }

        // Read pulse width
        pulse_width = read_pulse_width();
        if (pulse_width < 0) {
            fprintf(stderr, "Failed to read pulse width. Continuing...\n");
            sleep(0.5);
            continue;
        }

        // Calculate distance
        distance = calculate_distance(pulse_width);

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Wait 0.5 seconds
        sleep(0.5);
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec sleep_time = {0, 1000000000}; // 1 millisecond
    struct gpiod_line_request_config config;
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "my_gpio_app";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Sleep for 1 millisecond
        nanosleep(&sleep_time, NULL);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Sleep for 1 millisecond
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d (BCM) released.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

int i2c_fd = -1; // I2C file descriptor

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an ADXL345 register
int adxl345_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an ADXL345 register
int adxl345_read_register(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the ADXL345
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the ADXL345 (set POWER_CTL register to measure mode)
    if (adxl345_write_register(i2c_fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print accelerometer data
    while (1) {
        unsigned char data[6];
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0, &data[0]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 1, &data[1]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 2, &data[2]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 3, &data[3]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 4, &data[4]) < 0) {
            close(i2c_fd);
            return 1;
        }
        if (adxl345_read_register(i2c_fd, ADXL345_REG_DATAX0 + 5, &data[5]) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Combine the two bytes to form a 16-bit signed integer
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        // Print the accelerometer data
        printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
    }

    // The program should never reach here due to the infinite loop.
    close(i2c_fd);
    return 0;
}

