            line = lines;
            break;
        }
        line = line->next;
    }

    if (!line) {
        fprintf(stderr, "Error: GPIO line not found to unexport.\n");
        return -1;
    }

    if (gpiod_line_release(line->next, "distance_sensor") < 0) {
        perror("Error releasing GPIO line");
        return -1;
