FILE *log_file;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_spi();
void set_pwm(int state);
void log_data(int state);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);

    gpioWrite(ENABLE_PIN, 1); // Enable the chip select
    gpioWrite(CS_PIN, 1);    // Deactivate chip select initially

    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Set PWM output
void set_pwm(int state) {
    gpioPWM(PWM_PIN, state);
    printf("PWM set to %d\n", state);
}

// Log data to file
void log_data(int state) {
    if (log_file != NULL) {
        fprintf(log_file, "State: %d\n", state);
        fflush(log_file); // Ensure data is written to disk immediately
    }
}

// Cleanup resources
void cleanup() {
    gpioWrite(ENABLE_PIN, 0); // Disable the chip select
    gpioWrite(CS_PIN, 0);    // Activate chip select
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

