#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define ECHO2_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define GPIO lines
#define TRIGGER_LINE 0
#define ECHO_LINE 1
#define ECHO2_LINE 2

// Define distance threshold (in cm)
#define DISTANCE_THRESHOLD 100.0

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line, *echo2_line;
