// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
long long echo_time(void);
float calculate_distance(long long time);
void report_state(float distance1, float distance2);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
