// Initialize GPIO pins
int init_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_LINE);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_LINE);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    echo2_line = gpiod_chip_get_line(chip, ECHO2_LINE);
    if (!echo2_line) {
        perror("Error getting echo2 line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(echo2_line);
        return -1;
    }

    ret = gpiod_line_request_input(echo_line, "echo", 0);
    if (ret < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(echo2_line);
        return -1;
    }

    ret = gpiod_line_request_input(echo2_line, "echo2", 0);
    if (ret < 0) {
        perror("Error requesting echo2 line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(echo2_line);
        return -1;
    }

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse(void) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "trigger";

    if (gpiod_line_request_output(trigger_line, "trigger", 1) < 0) {
        perror("Error requesting trigger line as output");
        exit(EXIT_FAILURE);
    }

    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 10; // 10 microseconds

    nanosleep(&delay, NULL);

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Error releasing trigger line as output");
        exit(EXIT_FAILURE);
    }
}

// Measure the echo pulse width
long long echo_time(void) {
    struct timespec start, end;
    long long pulse_width;

    // Wait for the echo line to go high
    do {
        clock_gettime(CLOCK_MONOTONIC, &start);
        if (gpiod_line_get_value(echo_line, "echo") == 0) {
            break;
        }
        usleep(1000); // Check every 1 us
    } while (1);

    // Wait for the echo line to go low
    do {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (gpiod_line_get_value(echo_line, "echo") == 1) {
            break;
        }
        usleep(1000); // Check every 1 us
    } while (1);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    return pulse_width;
}

// Calculate distance in centimeters
float calculate_distance(long long time) {
    return (float)time / 29.1 / 2.0; // Speed of sound: 343 m/s, divided by 2 for one-way distance
}

// Report the state
void report_state(float distance1, float distance2) {
    printf("Distance 1: %.2f cm, Distance 2: %.2f cm\n", distance1, distance2);
}

// Cleanup GPIO pins
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (echo2_line) {
        gpiod_line_release(echo2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

