#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting...\n", signum);
}

int setup_uart(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = TIMEOUT_MS / 100;              // Timeout of 100ms

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart(int fd, char *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // No data available
        }
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd = setup_uart(UART_PORT, BAUD_RATE);
    if (fd == -1) {
        fprintf(stderr, "Failed to initialize UART. Exiting.\n");
        return EXIT_FAILURE;
    }

    char buffer[256];
    time_t last_read_time = time(NULL);

    while (program_running) {
        ssize_t bytes_read = read_uart(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
        } else if (bytes_read == -1) {
            // Handle read error, possibly retry or exit
            fprintf(stderr, "Error reading from UART. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        time_t current_time = time(NULL);
        if (difftime(current_time, last_read_time) >= 0.1) {
            bytes_read = read_uart(fd, buffer, sizeof(buffer) - 1);
            if (bytes_read > 0) {
                buffer[bytes_read] = '\0';
                printf("Received: %s", buffer);
            } else if (bytes_read == -1) {
                fprintf(stderr, "Error reading from UART. Retrying...\n");
                sleep(1); // Wait before retrying
            }
            last_read_time = current_time;
        }
        usleep(10000); // Sleep for 10ms to reduce CPU usage
    }

    close(fd);
    printf("UART port closed.\n");
    return EXIT_SUCCESS;
}

