// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main(void) {
    struct timespec start_time, end_time;
    double elapsed_time;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Trigger a pulse
        trigger_pulse();

        // Measure echo pulse duration
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Wait for echo to start
        while (1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            elapsed_time = (now.tv_sec - start_time.tv_sec) + (now.tv_nsec - start_time.tv_nsec) / 1000000000.0;
            if (elapsed_time > 0.1) break; // Timeout after 0.1 seconds
        }

        clock_gettime(CLOCK_MONOTONIC, &end_time);

        // Calculate elapsed time
        elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        // Print the elapsed time
        printf("Elapsed time: %.6f\n", elapsed_time);

        // Small delay to avoid busy-waiting
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 10000000; // 10 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

// Initialize GPIO lines
int init_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger pin
    line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!line) {
        perror("Error getting trigger pin");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo pin
    line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line) {
        perror("Error getting echo pin");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for input
    ret = gpiod_line_request_input(line, "echo", 0); // 0 for no flags
    if (ret < 0) {
        perror("Error requesting GPIO line for input");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line, "trigger", 0); // 0 for no flags
    if (ret < 0) {
        perror("Error requesting GPIO line for input");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set up interrupt for echo pin
    ret = gpiod_line_request_edge(line, "rising", 0); // 0 for no flags
    if (ret < 0) {
        perror("Error requesting GPIO line for interrupt");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Store lines in a linked list
    lines = (struct gpiod_line *)malloc(sizeof(struct gpiod_line));
    if (!lines) {
        perror("Error allocating memory for GPIO lines");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return -1;
    }
    lines->next = NULL;
    lines->consumer = line;

    gpiod_line *current = lines;
    while (current->next) {
        current = current->next;
        current->consumer = line;
    }
    current->consumer = line;

    return 0;
}

// Generate a trigger pulse
void trigger_pulse(void) {
    struct timespec duration;
    duration.tv_sec = 0;
    duration.tv_nsec = 10; // 10 microseconds

    // Set trigger pin high
    gpiod_line_set_value(lines->consumer, 1);

    // Wait for the specified duration
    nanosleep(&duration, NULL);

    // Set trigger pin low
    gpiod_line_set_value(lines->consumer, 0);
}

// Callback function for echo pin interrupt
void echo_callback(struct gpiod_line *line, unsigned int edge, unsigned int value) {
    struct timespec start_time, end_time;
    double elapsed_time;

    // Measure echo pulse duration
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Wait for echo to start
    while (1) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_time = (now.tv_sec - start_time.tv_sec) + (now.tv_nsec - start_time.tv_nsec) / 1000000000.0;
        if (elapsed_time > 0.1) break; // Timeout after 0.1 seconds
    }

    clock_gettime(CLOCK_MONOTONIC, &end_time);

    // Calculate elapsed time
    elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

    // Print the elapsed time
    printf("Echo pulse duration: %.6f\n", elapsed_time);
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    struct gpiod_line *current = lines;
    struct gpiod_line *next;

    // Unregister interrupt handler
    gpiod_line_set_callback(lines->consumer, NULL);

    // Free GPIO lines
    while (current) {
        next = current->next;
        gpiod_line_free(current->consumer);
        current = next;
    }

    // Free linked list
    free(lines);

    // Close GPIO chip
    gpiod_chip_close(CHIP_NAME);
}

