    }

    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!gpio_line_2) {
        perror("Error getting GPIO line 2");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "my_gpio", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line_2, "my_gpio_2", 0) < 0) {
        perror("Error requesting GPIO line 2 as output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO value
int set_gpio_value(int gpio_pin, int value) {
    if (gpio_pin != GPIO_PIN && gpio_pin != GPIO_PIN_2) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    int ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    int ret_2 = gpiod_line_set_value(gpio_line_2, value);
    if (ret_2 < 0) {
        perror("Error setting GPIO value 2");
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
int cleanup_gpio(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

int main(void) {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("GPIO initialized successfully.\n");

    // Main loop
    while (1) {
        // Set GPIO 17 to HIGH
        if (set_gpio_value(GPIO_PIN, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to HIGH.\n", GPIO_PIN);
        } else {
            printf("GPIO %d set to HIGH\n", GPIO_PIN);
        }

        // Set GPIO 18 to LOW
        if (set_gpio_value(GPIO_PIN_2, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to LOW.\n", GPIO_PIN_2);
        } else {
            printf("GPIO %d set to LOW\n", GPIO_PIN_2);
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

