    line24 = gpiod_chip_get_line(chip, GPIO24);

    if (!line18 || !line23 || !line24) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line18, "output", 0);
