    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO23, strerror(errno));
        gpiod_line_release(line18);
        gpiod_line_release(line23);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line24, "output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO24, strerror(errno));
        gpiod_line_release(line18);
        gpiod_line_release(line23);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Set GPIO states
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value: %s\n", GPIO18, strerror(errno));
        } else {
            printf("GPIO %d set to HIGH\n", GPIO18);
        }

        ret = gpiod_line_set_value(line23, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value: %s\n", GPIO23, strerror(errno));
        } else {
            printf("GPIO %d set to HIGH\n", GPIO23);
        }

        ret = gpiod_line_set_value(line24, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value: %s\n", GPIO24, strerror(errno));
        } else {
            printf("GPIO %d set to HIGH\n", GPIO24);
        }

        // Sleep for 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line18);
    gpiod_line_release(line23);
    gpiod_line_release(line24);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO control program finished.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

// I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, unsigned char reg) {
    unsigned char buffer[1];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, buffer, 1) == 1) {
                return buffer[0];
            } else {
                perror("Failed to read from I2C");
                retries--;
                usleep(10000); // Wait 10ms before retrying
            }
        } else {
            perror("Failed to write to I2C");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buffer[2];
    buffer[0] = reg;
    buffer[1] = value;

    if (write(fd, buffer, 2) == 2) {
        return 0; // Success
    } else {
        perror("Failed to write to I2C");
        return -1; // Indicate failure
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (write_register(i2c_fd, PWR_MGMT_1, 0) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        int accel_x_high = read_register(i2c_fd, ACCEL_XOUT_H);
        int accel_x_low = read_register(i2c_fd, ACCEL_XOUT_H + 1);
        int accel_y_high = read_register(i2c_fd, ACCEL_XOUT_H + 2);
        int accel_y_low = read_register(i2c_fd, ACCEL_XOUT_H + 3);
        int accel_z_high = read_register(i2c_fd, ACCEL_XOUT_H + 4);
        int accel_z_low = read_register(i2c_fd, ACCEL_XOUT_H + 5);

        if (accel_x_high < 0 || accel_x_low < 0 || accel_y_high < 0 || accel_y_low < 0 || accel_z_high < 0 || accel_z_low < 0) {
            fprintf(stderr, "Error reading accelerometer data. Exiting.\n");
            break;
        }

        // Combine high and low bytes to form 16-bit signed integer
        int16_t accel_x = (int16_t)((accel_x_high << 8) | accel_x_low);
        int16_t accel_y = (int16_t)((accel_y_high << 8) | accel_y_low);
        int16_t accel_z = (int16_t)((accel_z_high << 8) | accel_z_low);

        // Print the accelerometer readings
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 600000000; // 0.6 seconds

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Set GPIO high
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO high");
        } else {
            printf("GPIO %d set HIGH\n", GPIO_PIN);
        }

        // Sleep for 0.6 seconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO low
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO low");
        } else {
            printf("GPIO %d set LOW\n", GPIO_PIN);
        }

        // Sleep for 0.6 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        perror("Error closing GPIO chip");
    }

    printf("GPIO control program finished.\n");
    return EXIT_SUCCESS;
}
